window.__SUM[21]={"LR000007":{"pair":"ADAM15 -> ITGA5","headline":"ADAM15 disintegrin domain engages integrin alpha5beta1 on MOLT-4 T cells, from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Metargidin Fc chimera bound MOLT-4 cells, and alpha5beta1 contributes to this binding; adhesion was mediated by the disintegrin domain and inhibited by RGD peptides [PMID:9914169]. Specificity was confirmed in solid-phase assays with purified recombinant integrins [PMID:9914169].","molecular_requirements":"The receptor is alpha5beta1; alpha5 alone is not shown. Adhesion is divalent-cation dependent and enhanced by Mn2+ [PMID:9914169].","affinity_potency":[],"species_and_systems":"Human proteins and human cell lines; ADAM15 ectodomain-Fc chimera [PMID:9914169].","localisation_and_range":"ADAM15 is a type I transmembrane glycoprotein and flagged not secreted [PMID:9914169] [flag].","caveats":"One paper, abstract only; alpha5beta1 only 'contributes' to binding. Two other judged rows were abstract-insufficient or different-entity.","key_references":[{"PMID":"9914169","why":"ADAM-15 binding to alpha5beta1 on MOLT-4 cells"}],"covers":["LR000007","LR003557"]},"LR000016":{"pair":"ADAM2 -> CD9","headline":"CD9 is required for high-avidity ADAM2 (fertilin beta) binding to egg alpha6beta1, but is not shown to contact ADAM2 directly.","interaction_type":"functional only","direction_and_effect":"Anti-CD9 mAb JF9 inhibits sperm-egg binding and fusion in a dose-dependent manner and disrupts binding of fertilin- or fertilin-beta-disintegrin-coated beads to eggs [PMID:10518536].","molecular_requirements":"High-avidity binding between fertilin beta (ADAM 2) and alpha6beta1 requires cooperation between alpha6beta1 and CD9 [PMID:10518536]. CD9 associates with beta1 integrins [PMID:10518536].","affinity_potency":[],"species_and_systems":"Mouse eggs and sperm [PMID:10518536]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"ADAM2 flagged non-secreted [flag]; sperm-egg membrane contact.","caveats":"Abstract read only. The curator note says CD9 is required for high-avidity binding but not shown to directly contact ADAM2; CD9 acts as a co-factor of the integrin, so this is an indirect, co-receptor-type relationship.","key_references":[{"PMID":"10518536","why":"Anti-CD9 blocks fertilin-bead binding and sperm-egg fusion in mouse"}],"covers":["LR000016","LR003566"]},"LR000025":{"pair":"ADAM9 -> ITGB5","headline":"ADAM9 disintegrin domain adhesion depends on alphaVbeta5; antibody-inhibition evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Myeloma cell adhesion to the recombinant ADAM9 (MDC-9) disintegrin domain was completely blocked by anti-alpha(v)beta(5) but not antibodies to other subunits; RGD peptides had no effect [PMID:11162558]. Curated effect: Stimulatory [flag].","molecular_requirements":"beta5 acts as part of alphaVbeta5; the alphaV partner is needed per the antibody target [PMID:11162558]. Binding was Mn2+/Ca2+ dependent.","affinity_potency":[],"species_and_systems":"Human; myeloma cells and recombinant disintegrin domain [PMID:11162558]. Mouse pair is ortholog-inferred.","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Abstract-only, antibody inhibition rather than direct binding [PMID:11162558]. Affinity not reported. No database record in this dossier.","key_references":[{"PMID":"11162558","why":"alphaVbeta5 antibody blocks adhesion to the disintegrin domain"}],"covers":["LR000025","LR003575"]},"LR005020":{"pair":"ADGRB1 -> RTN4R","headline":"ADGRB1 ectodomain binds RTN4R directly in a CRISPRa and AVEXIS study; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probe stained cells overexpressing RTN4R, RTN4RL1 and RTN4RL2 and ectodomains interacted directly in AVEXIS in both bait-prey orientations [PMID:30477585]. Notably, RTN4R was not enriched in the CRISPRa screen (a false negative is acknowledged for one family member) and was confirmed by individual transfection and AVEXIS [PMID:30477585].","molecular_requirements":"The N-terminal thrombospondin type 1 repeats 1-3 of ADGRB1 were sufficient for binding; ADGRB1 but not ADGRB2 interacted [PMID:30477585].","affinity_potency":[],"species_and_systems":"Human cDNAs in HEK293 cells and recombinant ectodomains; four independent experiments for the staining result [PMID:30477585]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor side is a GPI-linked membrane protein per the paper [PMID:30477585]; ADGRB1 is flagged secreted [flag] but the assay used its ectodomain, and its native range is not reported in our evidence.","caveats":"Single paper; binding only, no signalling or functional effect shown. No affinity value. No database support.","key_references":[{"PMID":"30477585","why":"CRISPRa screen and AVEXIS showing ADGRB1-RTN4R family binding"}],"covers":["LR001632","LR005020"]},"LR000034":{"pair":"ADM -> CALCR","headline":"Adrenomedullin activates CTR with low potency alone; potency rises with RAMP (one abstract-only paper plus GtoPdb).","interaction_type":"functional only","direction_and_effect":"With hCTR(I1-) alone, hAM raised cAMP but remained about 100-fold less potent than hCT; co-expression with RAMP increased apparent AM potency toward that of CT [PMID:12565884]. GtoPdb lists ADM as full agonist [DB:GtoPdb].","molecular_requirements":"RAMP co-expression increases AM potency; the combination is sensitive to salmon CT-(8-32), not hAM-(22-52) [PMID:12565884].","affinity_potency":[{"value":"pEC50 6.5-8.4","assay":"GtoPdb agonist record","system":"not specified","cite":"PMID:12565884"}],"species_and_systems":"Human receptor transfected in HEK-293 cells [PMID:12565884].","localisation_and_range":"ADM flagged secreted [flag].","caveats":"Functional cAMP data only; no binding data. Alone, potency is about 100-fold lower than calcitonin [PMID:12565884]. Two further rows pending and one abstract_insufficient.","key_references":[{"PMID":"12565884","why":"cAMP response of CTR with and without RAMP"}],"covers":["LR000034","LR003584"]},"LR000043":{"pair":"AGRP -> MC5R","headline":"AGRP(87-132) binds cells expressing MC5R and inhibits alpha-MSH signalling in one abstract-only paper; weaker than at MC3R and MC4R.","interaction_type":"direct binding","direction_and_effect":"[125I]AGRP(87-132) bound only to cells expressing MC3R, MC4R and MC5R in conventional and photoemulsion binding studies [PMID:9892020]. AGRP(87-132) dose-dependently inhibited alpha-MSH-generated cAMP at cloned melanocortin receptors [PMID:9892020]. GtoPdb lists an antagonist interaction [DB:GtoPdb].","molecular_requirements":"The C-terminal cysteine-rich domain AGRP(87-132), a 46-amino acid variant, is equipotent to an 111-amino acid variant; N-terminal deletion did not alter receptor subtype specificity [PMID:9892020]. NDP-MSH and the AGRP fragment displace each other competitively [PMID:9892020].","affinity_potency":[{"value":"pIC50 6.5","assay":"inhibition of alpha-MSH-generated cAMP / binding","system":"cloned melanocortin receptor, human AGRP(87-132)","cite":"PMID:9892020"}],"species_and_systems":"Chemically synthesised human AGRP(87-132) and a mouse [Leu127Pro]AGRP variant on cloned receptors; curation tags human/human [PMID:9892020].","localisation_and_range":"AGRP is flagged secreted [flag].","caveats":"Single abstract-only paper. The abstract does not say which receptor the pIC50 6.5 refers to; the curator tied it to MC5R, and the value is lower than the pIC50 values given for MC3R and MC4R elsewhere. Direct competition with NDP-MSH is shown for the melanocortin receptors collectively [PMID:9892020].","key_references":[{"PMID":"9892020","why":"Binding and cAMP inhibition by synthetic AGRP(87-132) at MC3R, MC4R and MC5R"}],"covers":["LR000043","LR003593"]},"LR002104":{"pair":"ANGPTL1 -> LAIR1","headline":"ANGPTL1 binds LAIR1-expressing cells in one paper; weak binding, no purified-protein assay for LAIR1 shown.","interaction_type":"direct binding","direction_and_effect":"Angptl1 bound LAIR1-overexpressing 293T cells [PMID:22660330]. Effect on LAIR1 signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor expressed in 293T cells and primary human cord blood cells; the pair's mouse version is projected from human [PMID:22660330].","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"Angptl1 binding to LAIR1+ human cord blood cells was described as relatively weak [PMID:22660330]. The paper's co-IP and surface plasmon resonance confirmations and its focus were on LILRB2, not LAIR1, so direct binding to LAIR1 rests on cell-binding assays. No affinity reported.","key_references":[{"PMID":"22660330","why":"Angptl1 binds LAIR1-overexpressing cells, weakly on cord blood cells"}],"covers":["LR002104","LR005430"]},"LR000061":{"pair":"ANGPTL3 -> ITGAV","headline":"Recombinant ANGPTL3 binds integrin alphaVbeta3; the evidence is for the heterodimer, not ITGAV alone.","interaction_type":"direct binding","direction_and_effect":"Recombinant ANGPTL3 bound alpha(v)beta(3) and induced alpha(v)beta(3)-dependent endothelial cell adhesion and migration, with phosphorylation of Akt, MAPK and FAK [PMID:11877390]. UniProt records the same [DB:UniProt].","molecular_requirements":"Evidence is for the alphaVbeta3 heterodimer; ITGAV alone is not tested in our evidence. The C-terminal fibrinogen-like domain alone was sufficient for adhesion and in vivo angiogenesis [PMID:11877390].","affinity_potency":[],"species_and_systems":"Endothelial cells and rat corneal assay; species of the recombinant protein not reported in our evidence [PMID:11877390]. The mouse pair is projected from human.","localisation_and_range":"ANGPTL3 is described as a liver-specific secreted factor [PMID:11877390]; ligand also flagged secreted [flag].","caveats":"Abstract-only evidence; no affinity. Co-IP failed to detect ANGPTL3 binding to Tie2 [PMID:11877390].","key_references":[{"PMID":"11877390","why":"ANGPTL3 binds alphaVbeta3 and promotes endothelial adhesion and migration"}],"covers":["LR000061","LR003611"]},"LR002113":{"pair":"ANGPTL4 -> ITGA5","headline":"cANGPTL4 binds and activates integrin \u03b15\u03b21; one abstract-level paper plus an IntAct SPR record.","interaction_type":"direct binding","direction_and_effect":"cANGPTL4 binds and activates integrin \u03b15\u03b21-mediated Rac1/PAK signalling first, weakening cell-cell contacts, before declustering VE-cadherin and claudin-5 [PMID:21841165]. The curator effect label is antagonist, though the text says activates (see flag).","molecular_requirements":"The acting ligand is the C-terminal fibrinogen-like domain (cANGPTL4), a proteolytic fragment, not full-length ANGPTL4 [PMID:21841165]. Receptor is the \u03b15\u03b21 heterodimer [PMID:21841165].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator fields; ANGPTL4-knockout mice in vivo [PMID:21841165]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; ITGA5 flagged non-secreted receptor [flag]; endothelial cell-surface binding.","caveats":"One paper, abstract only. An IntAct record (surface plasmon resonance, PMID 21397862) is listed under accession P05556, the same accession shown for the \u03b21 pair, so it may not be \u03b15-specific [DB:IntAct].","key_references":[{"PMID":"21841165","why":"cANGPTL4 binds and activates integrin \u03b15\u03b21 first"}],"covers":["LR002113","LR005435"]},"LR002122":{"pair":"ANGPTL5 -> LILRB2","headline":"ANGPTL5 binds LILRB2 directly: flow cytometry, co-IP, SPR and a saturation binding assay.","interaction_type":"direct binding","direction_and_effect":"Human LILRB2 expressed on BAF3 cells enabled specific binding of GST-Angptl5, confirmed by co-IP with purified proteins and SPR [PMID:22660330]. LILRB2 is described as an immune inhibitory receptor; the signalling effect of ANGPTL5 binding is not shown in our excerpts [PMID:22660330].","molecular_requirements":"LILRB2 alone is sufficient for binding in overexpression systems; tagging type or position can affect binding [PMID:22660330].","affinity_potency":[{"value":"5.5 \u00b1 1.1 nM","assay":"half-maximal saturation, 125I-GST-Angptl5 liquid-phase binding","system":"cell-surface LILRB2","cite":"PMID:22660330"}],"species_and_systems":"Human LILRB2 on BAF3 and 293T cells and purified proteins [PMID:22660330]. Only a human pair.","localisation_and_range":"ANGPTL5 flagged secreted; LILRB2 transmembrane [flag]; soluble ligand to cell-surface receptor.","caveats":"Binding data use a GST-tagged ANGPTL5. An IntAct record from PMID 24899623 (FACS) is also listed [DB:IntAct].","key_references":[{"PMID":"22660330","why":"Angptls bind LILRB2; saturation binding of GST-Angptl5"}],"covers":["LR002122"]},"LR002131":{"pair":"APLP1 -> CNTN5","headline":"APLP1 binds CNTN5 ectodomain in a systematic binding screen with crystal-structure context; direction as ligand to receptor is arbitrary for this adhesion pair.","interaction_type":"direct binding","direction_and_effect":"APLP1 interacts with CNTN5; the paper reports that APP and APLP1 interact with CNTN3-5 [PMID:34958801]. Signalling direction or agonist/antagonist effect is not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins to transmit signals [PMID:34958801].","molecular_requirements":"Interaction involves the second fibronectin type III repeat of the contactin and the copper-binding domain of the amyloid protein, a conserved interface across five CNTN-amyloid structures [PMID:34958801]. Binding was tested with the APLP1 E1 domain and FN1-FN3 fragments of CNTN3-5 by biolayer interferometry [PMID:34958801]. APLP1 appeared to bind CNTN5 less strongly than CNTN4 [PMID:34958801]; CNTN5 and APLP1 form coreceptor complexes at presynaptic sites in cultured hippocampal neurons, per the authors' discussion of prior work (background) [PMID:34958801].","affinity_potency":[],"species_and_systems":"Human proteins in AlphaScreen extracellular binding assay and biolayer interferometry; zebrafish used for expression and some structures [PMID:34958801]. The mouse pair is inferred from human evidence.","localisation_and_range":"Contactins are GPI-anchored to the membrane [PMID:34958801]. Interaction could occur in cis on the same cell or in trans across cells [PMID:34958801]. Entity flags list APLP1 as secreted [flag], which conflicts with a membrane-anchored role.","caveats":"Paper was read for evidence as abstract per the curator, with full-text excerpts available [PMID:34958801]. The authors note that their BLI affinities are weaker than earlier reported values for APP and APLP1 with CNTN3-5 (17-35 nM), attributed to oligomeric state [PMID:34958801]. No APLP1-specific Kd is in our excerpts. IntAct has a pull-down record [DB:IntAct].","key_references":[{"PMID":"34958801","why":"Systematic binding and structural study of contactin-amyloid pairs."}],"covers":["LR002131","LR005448"]},"LR002140":{"pair":"APOB -> SCARB1","headline":"SR-BI enhances Lp(a) and apoB uptake in one abstract; apoB is tested as a particle component only.","interaction_type":"functional only","direction_and_effect":"SR-BI expression enhanced association of protein from Lp(a) and cellular internalization of apolipoprotein B; mice lacking or overexpressing SR-BI had decreased or increased plasma clearance of Lp(a) [PMID:23812625].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human SR-BI in HEK293 and HeLa cells; mouse knockout and transgenic mice [PMID:23812625].","localisation_and_range":"SCARB1 carries a receptor flag; APOB flagged secreted [flag].","caveats":"The ligand is Lp(a), not isolated apoB, and direct apoB binding is not shown. Abstract only; one paper.","key_references":[{"PMID":"23812625","why":"SR-BI-dependent Lp(a) uptake including apoB internalization"}],"covers":["LR002140"]},"LR012040":{"pair":"BAMBI -> BMPR1A:BMPR2","headline":"BAMBI to BMPR1A:BMPR2 has no verified paper; support is limited to one BioGRID record that names a different receptor chain pair.","interaction_type":"database-asserted only","direction_and_effect":"The pair is annotated as Inhibitory [flag]; no paper in our evidence confirms this direction. BioGRID lists BMPR1B-BAMBI: Reconstituted Complex [DB:BioGRID 726964].","molecular_requirements":"Complex members are BMPR1A and BMPR2; the BioGRID record concerns BMPR1B only, which is not a member of this complex [DB:BioGRID 726964]. Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the BioGRID experiment is not given; the pair is human.","localisation_and_range":"Receptor complex is flagged transmembrane [flag]; BAMBI has no annotation flags for secretion.","caveats":"Judged papers were abstract_insufficient or different_entity, so no paper confirms it; the evidence rests on a single database record.","key_references":[],"covers":["LR012040"]},"LR000106":{"pair":"BMP10 -> ACVRL1","headline":"Well supported: BMP10 binds ALK1 (ACVRL1) in structural and binding studies and activates it in endothelial cells.","interaction_type":"direct binding","direction_and_effect":"BMP10 acts as an ALK1 agonist, activating signalling in endothelial cells [PMID:17068149; PMID:32238803]. It is called 'a potent ALK1 ligand' and, with BMP9, potently inhibits endothelial migration and growth and induces ALK1-responsive genes [PMID:17068149].","molecular_requirements":"Crystal structure of the BMP10:ALK1 extracellular domain complex at 2.3 A shows 2:2 stoichiometry with the two ALK1 monomers not in contact [PMID:32238803]. BMP10 and BMP9 bind ALK1 with similar affinity whether or not the prodomain is present [PMID:32238803]. A type II receptor is not required for this binding result; BMP10 does not discriminate among type II receptors [PMID:22718755].","affinity_potency":[],"species_and_systems":"Human recombinant proteins for binding and structure [PMID:32238803; PMID:22718755]; microvascular endothelial cells for function [PMID:17068149]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"All three papers were read as abstracts (excerpts for one). No numeric affinity is given in our evidence, only 'similar affinities' or 'comparable affinity'. The ALK1 ternary structure in the 2012 paper is of BMP9, not BMP10.","key_references":[{"PMID":"32238803","why":"Crystal structure of BMP10:ALK1; prodomain does not interfere"},{"PMID":"22718755","why":"Kinetic/thermodynamic binding of BMP9/BMP10 to ALK1 and type II receptors"},{"PMID":"17068149","why":"BMP10 as an ALK1 ligand in endothelial cells"}],"covers":["LR000106","LR003655"]},"LR000115":{"pair":"BMP15 -> BMPR2","headline":"Well supported: BMP15 binds BMPR2 in radioligand and SPR assays, with a functional neutralisation result as well.","interaction_type":"direct binding","direction_and_effect":"A radiolabelled BMP15 covalent-dimer variant bound endogenous BMPR2 (with BMPR1B) on COV434 cells and in COS cells overexpressing them [PMID:22294741]. BMPR2 high-affinity growth factors include BMP15, BMP10 and Nodal [PMID:35643319]. The BMPRII ectodomain most effectively blocked BMP15 activity in granulosa cells [PMID:12419820].","molecular_requirements":"BMPR2 acted with BMPR1B in the signalling complex [PMID:22294741].","affinity_potency":[{"value":"KD 6.3E-09 M (SD 1.0E-09)","assay":"SPR, BMP15 over captured BMPRII-Fc","system":"recombinant proteins","cite":"PMID:35643319"}],"species_and_systems":"Human recombinant BMP15, COV434 and COS cells [PMID:22294741]; rat primary granulosa cells [PMID:12419820]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP15 is annotated as secreted [flag]; paracrine from oocyte per the 2012 abstract [PMID:22294741].","caveats":"All abstracts; the KD comes from a table in full-text excerpts, which also says BMP15 had fast association and dissociation [PMID:35643319]. Only the engineered covalent dimer kept binding after iodination [PMID:22294741].","key_references":[{"PMID":"22294741","why":"Radioligand binding of BMP15 to BMPR1B/BMPR2"},{"PMID":"35643319","why":"SPR affinity of BMP15 for BMPR2"},{"PMID":"12419820","why":"BMPRII ectodomain neutralises BMP15"}],"covers":["LR000115","LR003664"]},"LR000124":{"pair":"BMP3 -> ACVR2A","headline":"BMP3 binds ACVR2A (ActRII) by SPR, but with low affinity; one paper, ortholog-projected.","interaction_type":"direct binding","direction_and_effect":"BMP-3 binds ActRII with Kd approximately 1.8 microM but ActRIIb with 30-fold higher affinity [PMID:17924656]. Mutating Ser-28 or Asp-33 of BMP-3 to alanine raised affinity up to 20-fold [PMID:17924656].","molecular_requirements":"The low affinity was attributed to Ser-28 and Asp-33 of BMP-3; the BMP-3-S28A mutant gave signalling comparable to BMP-6 in a Smad-luciferase assay [PMID:17924656].","affinity_potency":[{"value":"Kd approximately 1.8 microM","assay":"SPR (BIAcore)","system":"purified proteins; species not reported","cite":"PMID:17924656"},{"value":"Kd approximately 53 nM","assay":"SPR (BIAcore), ActRIIb comparator","system":"purified proteins; species not reported","cite":"PMID:17924656"}],"species_and_systems":"SPR with recombinant proteins; species not reported. Both human and mouse pairs are projected from other evidence (ortholog_inferred).","localisation_and_range":"BMP3 flagged secreted and ACVR2A transmembrane [flag].","caveats":"Single paper read as abstract; the micromolar affinity suggests a weak interaction relative to ActRIIb. No database records.","key_references":[{"PMID":"17924656","why":"SPR shows BMP-3 binds ActRII weakly (microM) and ActRIIb tighter"}],"covers":["LR000124","LR003673"]},"LR000133":{"pair":"BMP6 -> ACVR1","headline":"BMP6 binds ALK-2 (ACVR1) in cross-linking assays, but only together with type II receptors; one 1999 paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist. In COS-7 cells, 125I-BMP-6 strongly bound ALK-2 together with the type II receptors BMPR-II and ActR-II [PMID:10504300]. UniProt (BMP6) says BMP6 initiates BMP signalling by associating with type I receptor ACVR1 and type II receptor ACVR2B [DB:UniProt][PMID:18070108]; GtoPdb lists BMP6 as agonist at ACVR1 [DB:GtoPdb].","molecular_requirements":"A type II receptor (BMPR-II or ActR-II) was needed for BMP-6 binding to ALK-2 in the paper's co-transfection experiments [PMID:10504300]. ACVR1 alone is not shown to bind BMP6 in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human BMP-6; receptor constructs in COS-7 cells (receptor species not explicitly stated); endogenous binding in mouse MC3T3-E1 and C2C12 cell lines [PMID:10504300]. The human and mouse pairs are both projected from this evidence.","localisation_and_range":"BMP6 is flagged secreted [flag]; receptor localisation not reported in our evidence.","caveats":"Affinity not reported. A third judged row was review_only. Binding in ROB-C26 cells to ALK-2 was described as less efficient than to BMPR-IB.","key_references":[{"PMID":"10504300","why":"cross-linking of 125I-BMP-6 to ALK-2 with type II receptors"}],"covers":["LR000133","LR003682"]},"LR000142":{"pair":"BMP7 -> BMPR1A","headline":"BMP7 binds BMPR1A (ALK-3) less efficiently than other type I receptors; support is from abstracts of 1990s binding papers.","interaction_type":"direct binding","direction_and_effect":"In transfected COS cells OP-1 bound ALK-3 less efficiently than ALK-2 and ALK-6, and also bound ALK-3 in some nontransfected cell lines with cell-type-dependent profiles [PMID:8006002]. BMPR-II binds BMP-7 in association with type I receptors including BMPR-IA [PMID:7791754]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"BMPR1A is a type I chain; binding in COS cells was seen without type II receptors and increased with co-transfected DAF-4 [PMID:8006002]. BMPR-II association is ligand dependent [PMID:7791754].","affinity_potency":[],"species_and_systems":"Human proteins in COS cells and various nontransfected cell lines [PMID:8006002]; cloned human BMPR-II in mammalian cells [PMID:7791754]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Both papers were read as abstracts only. BMPR1A is a secondary BMP7 receptor relative to ALK-2/ALK-6 in the 1994 study [PMID:8006002]. PMID 7791754 is a BMPR-II study and shows BMP7 with BMPR-IA only in a type II context. Two papers were abstract_insufficient and one review_only.","key_references":[{"PMID":"8006002","why":"OP-1 binds ALK-3 less efficiently than ALK-2/ALK-6"},{"PMID":"7791754","why":"BMPR-II binds BMP-7 in association with BMPR-IA"}],"covers":["LR000142","LR003691"]},"LR011203":{"pair":"BMP8B -> ACVR2A","headline":"BMP8B -> ACVR2A rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR2A [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR011203"]},"LR002203":{"pair":"C1QB -> CD44","headline":"CD44 mediates C1q signalling and chemotaxis in human neural stem cells; functional plus proximity-ligation support from one paper.","interaction_type":"functional only","direction_and_effect":"CRISPR-Cas9 CD44 knockout was used to test that CD44 mediates C1q-induced signalling (p-ERK) and chemotaxis in hNSC; the abstract reports CD44 mediates these effects in vitro and hNSC migration and repair in vivo after spinal cord injury [PMID:32894219]. Stimulatory.","molecular_requirements":"The ligand studied was assembled C1q (C1QA:C1QB:C1QC), not the single C1QB chain; chain-alone activity is not shown [PMID:32894219]. Co-receptor or subunit requirements on the CD44 side are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neural stem cells in vitro (CD44 identified among five candidate C1q receptors by crosslinking and mass spectrometry, then proximity ligation assay indicating close contact <30 nm); in vivo spinal cord injury model, host species not stated in the excerpts [PMID:32894219].","localisation_and_range":"C1q is secreted (ligand flag); CD44 is flagged as transmembrane and also secreted [flag]. Acts on cell-surface CD44 of the responding cell [PMID:32894219].","caveats":"Curated from the abstract plus excerpts. Proximity ligation shows nearness, not a measured affinity; no Kd reported. Mouse interaction is ortholog-inferred only.","key_references":[{"PMID":"32894219","why":"CD44 identified as C1q receptor on hNSC; knockout abolishes C1q-induced signalling/chemotaxis"}],"covers":["LR002203","LR005517"]},"LR002212":{"pair":"C1QC -> LAIR1","headline":"C1q (via its collagen-like region) binds and activates LAIR-1 on human monocytes; one paper, chain-level row.","interaction_type":"direct binding","direction_and_effect":"The abstract states that C1q CLR engaging and activating LAIR-1 is a non-complement route to immune quiescence, and that C1q crosslinks LAIR-1 and CD33 [PMID:28325905]. The CLR-LAIR-1 activation is stated in the abstract's first sentence; in this paper's excerpts, C1q bound LAIR-1 in a dose-dependent manner on HEK293T lysates, described as previously reported by the authors.","molecular_requirements":"Domain-resolved: the collagen-like region (CLR) of C1q engages LAIR-1, whereas the globular head binds CD33 [PMID:28325905]. This row encodes the C1QC chain of the hexameric C1q; chain-alone activity is not shown.","affinity_potency":[],"species_and_systems":"Human: HEK293T cells transfected with LAIR-1 (slot blot), human monocytes (proximity ligation assay) [PMID:28325905].","localisation_and_range":"C1q secreted (ligand flag), LAIR1 transmembrane (receptor flag) [flag]; C1q bridges LAIR-1 and CD33 on one monocyte [PMID:28325905].","caveats":"The LAIR-1 arm is largely background in this paper (the new claim is CD33); the visible abstract does not give the LAIR-1 measurement. Single paper; chain-level attribution inherited from the complex.","key_references":[{"PMID":"28325905","why":"C1q CLR engages LAIR-1 and bridges it with CD33 on human monocytes"}],"covers":["LR002212","LR005525"]},"LR002221":{"pair":"C1QTNF8 -> RXFP1","headline":"CTRP8 is reported to bind and activate RXFP1 in human glioblastoma cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"CTRP8 (secreted, recombinant human, or short synthetic peptides from its C1q globular domain) activated RXFP1, measured as elevated intracellular cAMP, and induced a pro-migratory phenotype in glioblastoma cell lines and primary patient cells; a competitor peptide disrupted CTRP8-RXFP1 motility [PMID:24014093]. Agonist.","molecular_requirements":"Homology and docking place the interaction at the N-terminal region of the CTRP8 globular C1q domain and leucine-rich repeat units 7 and 8 of RXFP1 [PMID:24014093]. Co-receptors not reported.","affinity_potency":[],"species_and_systems":"Human: HEK293T-secreted CTRP8, recombinant human CTRP8, glioblastoma cell lines and primary patient cells; co-immunoprecipitation showed direct interaction of human CTRP8 with RXFP1 [PMID:24014093]. BioGRID Affinity Capture-Western and UniProt agree [DB:BioGRID, DB:UniProt].","localisation_and_range":"CTRP8 secreted and RXFP1 transmembrane per flags [flag]; paracrine or autocrine range not reported.","caveats":"Abstract only; the classical RXFP1 ligands RLN1-3 are absent in this tumour type, so relevance elsewhere is unknown. Single paper, no affinity value.","key_references":[{"PMID":"24014093","why":"CTRP8 as novel RXFP1 ligand in human glioblastoma, with co-IP and cAMP"}],"covers":["LR002221"]},"LR000160":{"pair":"C3 -> ITGB2","headline":"C3 fragments bind the CD18 (ITGB2)-containing integrins; supported by binding papers, but the beta chain alone is not shown sufficient.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose isolated CR3 and p150,95, which share a beta2 subunit [PMID:4062888]. C3(H2O) bound recombinant CD11b/CD18 directly by quartz crystal microbalance and flow cytometry [PMID:26293614]. iC3b-erythrocytes bound Mac-1 transfectants [PMID:7679388].","molecular_requirements":"Binding is by alpha:beta2 heterodimers; the I domain of the alpha chain is the recognition site [PMID:7679388]. Whether ITGB2 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins: membranes, recombinant CD11b/CD18, COS transfectants [PMID:4062888][PMID:26293614][PMID:7679388]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane integrin; contact-dependent (annotation [flag]).","caveats":"Two papers abstract only; PMID 7679388 full-text excerpt only mentions iC3b-E binding as a control (data not shown). Evidence is for the alpha:beta2 complexes, so the ITGB2 chain row is chain-level. Ligand forms are iC3b or C3(H2O).","key_references":[{"PMID":"26293614","why":"Direct C3(H2O)-CD11b/CD18 binding"},{"PMID":"4062888","why":"iC3b affinity isolation of beta2 integrins"}],"covers":["LR000160","LR003709"]},"LR002230":{"pair":"CADM2 -> CADM3","headline":"Direct CADM2-CADM3 heterophilic binding detected by SPRi in one paper.","interaction_type":"direct binding","direction_and_effect":"SPRi detected heterophilic interactions of CADM2 and CADM3 with all CADM family proteins [PMID:30131958]. No effect direction reported.","molecular_requirements":"Whole ectodomain Fc fusions; no other subunit reported [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human-labelled recombinant ectodomains in SPRi [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag]; Reactome has Necl homodimer entries only [DB:Reactome].","caveats":"One paper. The curated sentence concerns CADM1 as analyte, so this pair rests on the general statement; no Kd for CADM2-CADM3 is reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family including CADM2-CADM3"}],"covers":["LR002230","LR005540"]},"LR000205":{"pair":"CCL17 -> CCR4","headline":"CCL17 (TARC) is a high-affinity, selective CCR4 agonist, confirmed by two binding papers and database records.","interaction_type":"direct binding","direction_and_effect":"Agonist: TARC bound CCR4 selectively among five CC receptors [PMID:9169480] and induced calcium mobilisation in CCR4 transfectants [PMID:9430724]. GtoPdb lists a full agonist [DB:GtoPdb]; UniProt says it acts by binding CCR4 on T cells [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 0.5 nM","assay":"TARC-SEAP binding","system":"K562 cells stably expressing CCR4","cite":"PMID:9169480"},{"value":"pIC50 8.7","assay":"binding competition (curator-recorded)","system":"CCR4-transfected L1.2 cells","cite":"PMID:9430724"}],"species_and_systems":"Human ligand and receptor in transfected K562 and L1.2 cells; abstract-only [PMID:9169480][PMID:9430724].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"The mouse pair is projected from human evidence. TARC did not desensitize the MDC response [PMID:9430724].","key_references":[{"PMID":"9169480","why":"Identifies CCR4 as the TARC receptor, Kd 0.5 nM"},{"PMID":"9430724","why":"Competition and signalling at CCR4"}],"covers":["LR000205","LR003733"]},"LR000232":{"pair":"CCL2 -> ACKR2","headline":"Direct binding of CCL2 to ACKR2 (D6), a promiscuous beta-chemokine receptor, with human CCL2 about 30-fold lower affinity than murine JE.","interaction_type":"direct binding","direction_and_effect":"hD6 binds most beta-chemokines with high affinity and did not flux calcium after ligand binding, so signalling capacity is unclear [PMID:9405404]; the second paper reports MCP-1 competing for MCP-3 binding with IC50 1.2 nM [PMID:9364936].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 1.2 nM","assay":"competition for MCP-3 binding","system":"receptor then named CCR10 (cloned human receptor)","cite":"PMID:9364936"}],"species_and_systems":"Human ligand and receptor, CHO cells stably expressing human D6 [PMID:9405404]. Mouse pair is ortholog-inferred. UniProt lists CCL2 among ACKR2 chemokine ligands [DB:UniProt].","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"The text states human MCP1 binds hD6 with approximately 30-fold lower affinity than the presumed murine homologue JE [PMID:9405404]. The 9364936 paper names its receptor CCR10, not ACKR2; the match is by curator assignment. Four other papers were review-only.","key_references":[{"PMID":"9405404","why":"hD6 characterisation, promiscuous binding, MCP1 lower affinity"},{"PMID":"9364936","why":"Binding of MCP-1 to cloned receptor, IC50 1.2 nM"}],"covers":["LR000232","LR003753"]},"LR000214":{"pair":"CCL20 -> CXCR3","headline":"Single weak competition-binding observation (Ki 140 nM); no functional evidence for CCL20 at CXCR3 in our dossier.","interaction_type":"direct binding","direction_and_effect":"In a competition-binding table, MIP-3alpha (CCL20) competed with 125I-IP10 on recombinant CXCR3 with 140 +/- 20 (nM Ki) [PMID:9660793]. The curator labelled it a full agonist, as does GtoPdb [DB:GtoPdb], but the paper's agonist data in our excerpt concern IP10, MIG and eotaxin, not CCL20.","molecular_requirements":"Not reported in our evidence beyond CXCR3 expressed in CHO cells.","affinity_potency":[{"value":"Ki 140 nM (140 +/- 20)","assay":"competition binding vs 125I-IP10","system":"CHO cells expressing human CXCR3","cite":"PMID:9660793"}],"species_and_systems":"Human ligand and human receptor in recombinant CHO cells [PMID:9660793]. The mouse pair is projected from human.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Rests on one paper, quoted from a table row read via browser (unverified quote). It is a weak competitor compared with IP10 and MIG (Ki 0.14 and 4.9 nM) [PMID:9660793]. Whether CCL20 activates CXCR3 is not shown in our evidence. Other papers judged were different-entity or abstract-insufficient.","key_references":[{"PMID":"9660793","why":"only paper; Ki 140 nM for CCL20 competition on CXCR3"}],"covers":["LR000214","LR003741"]},"LR008797":{"pair":"CCL27 -> ACKR2","headline":"All confirmed papers concern CCL27 and CCR10 (GPR2), not ACKR2; the receptor assignment looks wrong.","interaction_type":"conflicting","direction_and_effect":"The papers show CCL27 (ESkine/CTACK) acts on GPR2/CCR10, causing migration and calcium flux in transfectants [PMID:10725696][PMID:10725697], and mediating skin-homing T cell chemotaxis [PMID:11821900]. No ACKR2 data are shown.","molecular_requirements":"Not reported in our evidence for ACKR2.","affinity_potency":[],"species_and_systems":"Human experiments for CCR10 [PMID:10725696][PMID:10725697][PMID:11821900].","localisation_and_range":"Ligand flagged secreted, ACKR2 flagged transmembrane [flag].","caveats":"The evidence does not support the stated ACKR2 partner; it supports CCR10. Abstracts only.","key_references":[{"PMID":"10725697","why":"CCL27 binds GPR-2, renamed CCR10"},{"PMID":"10725696","why":"GPR2 identified as ESkine receptor"}],"covers":["LR008797"]},"LR000241":{"pair":"CCL3L1 -> CCR1","headline":"LD78beta (mapped to CCL3L1) binds CCR1, with the CD26-processed form binding tenfold better; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"LD78beta(3-70) competed tenfold more efficiently than LD78beta(1-70) with [125I]RANTES for binding to CCR1 and CCR5 [PMID:11449371]. Curators label it an agonist.","molecular_requirements":"The N-terminal Ala-Pro dipeptide cleaved by CD26 gives the more potent LD78beta(3-70) form at CCR1 [PMID:11449371].","affinity_potency":[],"species_and_systems":"Human ligand and receptor [PMID:11449371]. BioGRID records a reconstituted complex [DB:BioGRID].","localisation_and_range":"CCL3L1 is flagged as secreted and CCR1 as transmembrane [flag].","caveats":"One paper, abstract only; no absolute affinity values in our evidence. The paper concerns the LD78beta isoform; its mapping to CCL3L1 comes from the curators.","key_references":[{"PMID":"11449371","why":"Processed LD78beta binds CCR1/CCR5 tenfold better"}],"covers":["LR000241"]},"LR008599":{"pair":"CCL3L3 -> ACKR2","headline":"LD78beta binds D6/ACKR2 with enhanced affinity over LD78alpha; a second paper names only the CC-chemokine class. Indirect for CCL3L3.","interaction_type":"direct binding","direction_and_effect":"LD78beta shows approximately 15-20-fold enhanced binding affinity to D6 compared with LD78alpha [PMID:10364178]. ACKR2 binds many inflammatory CC chemokines but does not signal or drive migration, so it acts as a scavenger [PMID:25297873].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; the D6 comparison is a receptor-binding assay [PMID:10364178]; trophoblast data are from primary human trophoblasts [PMID:25297873].","localisation_and_range":"CCL3L3 is flagged as secreted and ACKR2 as transmembrane [flag].","caveats":"Both papers were read as abstracts only. PMID 25297873 names the CC-chemokine class, not CCL3L3, and the curators note medium confidence. Absolute affinity values are not reported in our evidence.","key_references":[{"PMID":"10364178","why":"LD78beta binds D6 with enhanced affinity"}],"covers":["LR008599"]},"LR000250":{"pair":"CCL4 -> ACKR2","headline":"Human D6/ACKR2 is promiscuous for beta-chemokines, but the verified paper names murine MIP-1b, not human CCL4; weak, indirect support.","interaction_type":"direct binding","direction_and_effect":"D6 (ACKR2) is a promiscuous beta-chemokine receptor with relatively high affinity for most beta-chemokines [PMID:9405404]. UniProt lists CCL4 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 in transduced cells, with displacement of radioiodinated murine MIP-1a; the highest-affinity ligands included murine MIP-1a and MIP-1b [PMID:9405404]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"CCL4 is flagged as secreted and ACKR2 as transmembrane [flag].","caveats":"No human CCL4 value appears in our excerpts; the pair rests on a murine ligand against the human receptor. Five review-only papers are not shown. No affinity numbers in our evidence.","key_references":[{"PMID":"9405404","why":"Cloning of human D6 with beta-chemokine binding"}],"covers":["LR000250","LR003764"]},"LR000421":{"pair":"CCN1 -> ITGAV","headline":"CCN1 binds integrin alphavbeta3 and alphavbeta5 directly; the alphav chain alone is not the functional unit.","interaction_type":"direct binding","direction_and_effect":"Purified alphavbeta3 bound Cyr61-Sepharose and soluble Cyr61 bound immobilized alphavbeta3, with endothelial adhesion blocked by RGDS and the alphavbeta3 antibody LM609 [PMID:9446626]. Cyr61 bound directly to purified alphavbeta5, which mediated fibroblast migration, while alphavbeta3 was linked to mitogenesis [PMID:11287419].","molecular_requirements":"ITGAV acts as a heterodimer: with beta5 for migration and with beta3 for mitogenesis enhancement [PMID:11287419]; alphavbeta3 adhesion was RGD-peptide sensitive and divalent-cation dependent [PMID:9446626].","affinity_potency":[{"value":"approximately 5 nM half-saturation","assay":"solid-phase binding, soluble Cyr61 to immobilized alphavbeta3","system":"purified integrin","cite":"PMID:9446626"}],"species_and_systems":"Human CCN1 (Cyr61), human umbilical vein endothelial cells and human skin fibroblasts, purified integrins. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Both papers were read as abstracts only. Half-saturation binding is not a formal Kd. One more paper was judged abstract-insufficient and one is pending.","key_references":[{"PMID":"9446626","why":"Direct alphavbeta3 binding with about 5 nM half-saturation"},{"PMID":"11287419","why":"Direct alphavbeta5 binding; distinct beta-chain roles"}],"covers":["LR000421","LR003918"]},"LR005101":{"pair":"CD99 -> PILRA","headline":"CD99 is a glycosylated ligand for PILR-alpha, shown by SPR with a Kd of about 2.2 \u03bcM.","interaction_type":"direct binding","direction_and_effect":"Inhibitory PILR-alpha binds CD99 with low affinity; activating PILR-beta binds about 40 times more weakly [PMID:18234675]. Reactome records PILRA,PILRB binding CD99 [DB:Reactome].","molecular_requirements":"Requires CD99 O-glycosylation; PILR-alpha binds each of the two O-glycosylated sites (Thr-45, Thr-50) independently and equivalently [PMID:18234675].","affinity_potency":[{"value":"Kd approximately 2.2 \u03bcM","assay":"SPR","system":"PILRalpha with CD99, human","cite":"PMID:18234675"}],"species_and_systems":"Human recombinant proteins, SPR [PMID:18234675]; mouse pair is the record's other species.","localisation_and_range":"Membrane-bound CD99; contact-dependent.","caveats":"Abstract only; low affinity with fast dissociation [PMID:18234675].","key_references":[{"PMID":"18234675","why":"SPR of PILR-CD99 binding"}],"covers":["LR001736","LR005101"]},"LR002302":{"pair":"CDH1 -> ITGA2","headline":"Pentameric E-cadherin binds integrin alpha2beta1; this entry names the alpha2 chain only.","interaction_type":"direct binding","direction_and_effect":"Pentameric but not monomeric E-cadherin bound purified alpha2beta1 and the recombinant A-domain of alpha2 in a divalent cation-dependent manner [PMID:12392763]. HT1080 adhesion was blocked by anti-alpha2 and anti-beta1 antibodies [PMID:12392763].","molecular_requirements":"alpha2beta1 heterodimer is the receptor; alpha2 A-domain binds on its own; beta1 role shown by antibody block [PMID:12392763].","affinity_potency":[],"species_and_systems":"Human HT1080 fibrosarcoma cells and purified integrin [PMID:12392763].","localisation_and_range":"Membrane-bound; adhesion.","caveats":"Abstract only; needs multivalent (pentameric) E-cadherin, suggesting low affinity; one paper.","key_references":[{"PMID":"12392763","why":"E-cadherin binds integrin alpha2beta1"}],"covers":["LR002302","LR005600"]},"LR002311":{"pair":"CDH2 -> CDH4","headline":"Only a BioGRID co-precipitation record; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. BioGRID lists CDH4 - CDH2 by Affinity Capture-Western [DB:BioGRID] [PMID:10662782].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both are flagged as membrane receptors; CDH2 is flagged transmembrane [flag].","caveats":"Seven papers were judged as different entity or abstract-insufficient, none confirmed. Affinity capture is not proof of direct binding.","key_references":[],"covers":["LR002311","LR005609"]},"LR002320":{"pair":"CDH8 -> CDH11","headline":"Preferred heterophilic type II cadherin pair in SPR on mouse proteins; human pair inferred.","interaction_type":"direct binding","direction_and_effect":"The cadherin-8 surface supported heterophilic binding of cadherin-11 as its strongest interaction, followed by homophilic cadherin-8 binding [PMID:29742438].","molecular_requirements":"Cadherin-8 and -11 form one specificity group preferring each other [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"Heterophilic cadherin-8/-11 SPR"}],"covers":["LR002320","LR005618"]},"LR000304":{"pair":"CLCF1 -> LIFR","headline":"LIFR is engaged only as a signalling chain of the CNTFR complex; evidence is functional activation, not direct binding.","interaction_type":"functional only","direction_and_effect":"The CLF/CLC complex activated gp130, LIFR and STAT3 and supported motor neuron survival [PMID:10966616]. CLC-CNTFR acted on cells expressing the gp130-LIFR complex [PMID:11285233]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"LIFR acts downstream of CNTFR: curator notes describe gp130/LIFR as signalling chains, not independent CLC binding partners [PMID:11285233]. CNTFR binding induces gp130 heterodimerisation with LIFR [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; abstract-level evidence only [PMID:10966616][PMID:11285233].","localisation_and_range":"Not reported in our evidence beyond annotation flags.","caveats":"Both papers abstract only. Direct CLCF1-LIFR binding is not shown; CNTFR is required.","key_references":[{"PMID":"10966616","why":"gp130 and LIFR activation by CLF/CLC"},{"PMID":"11285233","why":"CLC-CNTFR activity on gp130-LIFR cells"}],"covers":["LR000304","LR003810"]},"LR005110":{"pair":"CNTN1 -> NOTCH1","headline":"F3/contactin reported as a functional Notch ligand in oligodendrocyte cells; abstract-only evidence plus database records.","interaction_type":"functional only","direction_and_effect":"F3/contactin acts as a functional ligand of Notch, signalling in OLN-93 oligodendrocyte cells and precursors [PMID:14567914].","molecular_requirements":"Not reported beyond the abstract. BioGRID lists affinity capture-Western and Reactome a CNTN1:NOTCH1:DTX complex [DB:BioGRID][DB:Reactome].","affinity_potency":[],"species_and_systems":"OLN-93 oligodendrocyte cell line; ligand and receptor species not specified in the curation row [PMID:14567914]. Human pair is ortholog-inferred.","localisation_and_range":"CNTN1 is flagged transmembrane [flag]; the paper calls F3 GPI-linked [PMID:14567914].","caveats":"Abstract-only read; the paper does not distinguish NOTCH1 from other Notch paralogs in our evidence; species not specified.","key_references":[{"PMID":"14567914","why":"F3/contactin as functional Notch ligand"}],"covers":["LR001752","LR005110"]},"LR000313":{"pair":"CNTN4 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN4; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN4 is annotated secreted and PTPRG non-secreted [flag].","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN4 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR000313","LR003819"]},"LR000322":{"pair":"COL1A1 -> CD44","headline":"Purified lymphocyte CD44 binds native type I collagen fibrils in one 1992 paper whose focus is fibronectin.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified CD44 bound native type I collagen fibrils, laminin and fibronectin, but not gelatin [PMID:1730778]. Effect on signalling: not reported in our evidence.","molecular_requirements":"Fibronectin binding was via the chondroitin sulfate-containing form of CD44 [PMID:1730778]; whether this applies to collagen: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Affinity-purified lymphocyte CD44 antigen in a protein binding assay [PMID:1730778]. Species is not stated in the dossier beyond lymphocytes.","localisation_and_range":"Receptor is a lymphocyte surface glycoprotein; collagen is matrix.","caveats":"Collagen binding is a side observation in a paper mainly about fibronectin; no affinity; abstract plus limited excerpts only. Not resolved to the COL1A1 chain.","key_references":[{"PMID":"1730778","why":"Purified CD44 binds native type I collagen fibrils"}],"covers":["LR000322","LR003828"]},"LR006889":{"pair":"COL1A1 -> ITGA1:ITGB1","headline":"Database-asserted only: a BioGRID co-purification record for COL1A1-ITGB1; no curator-confirmed paper for this complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect: not reported in our evidence.","molecular_requirements":"The database record names ITGB1 alone, so the alpha chain is not established [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BioGRID lists a co-purification for COL1A1-ITGB1 [DB:BioGRID, PMID:2156854]. Species not reported in our evidence.","localisation_and_range":"Receptor is a transmembrane complex [flag]; collagen is a matrix ligand.","caveats":"No papers were judged confirmed; curator read counts are only review_only and abstract_insufficient. Support rests on one database record.","key_references":[],"covers":["LR006889"]},"LR000331":{"pair":"COL1A2 -> ITGA1","headline":"Alpha1 I-domain bound type I collagen by SPR in one full-text paper; evidence is for the intact heterotrimer.","interaction_type":"direct binding","direction_and_effect":"alpha1 I-domain bound fibrillar collagen types I-III with similar affinities [PMID:16043429]. Annotated effect is stimulatory.","molecular_requirements":"Recombinant alpha1 I-domain alone was sufficient in vitro; the beta1 partner is not tested here [PMID:16043429].","affinity_potency":[{"value":"Kd 0.3 uM (range 0.15-1.75 uM)","assay":"SPR (BIAcore), two affinity classes, reported for the study","system":"recombinant human I-domains, purified fibrillar collagen","cite":"PMID:16043429"}],"species_and_systems":"Human recombinant I-domains and purified collagen [PMID:16043429].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"The Kd is a range for the study's interactions and may not be specific to alpha1 or to type I collagen. Collagen I was tested as the (COL1A1)2COL1A2 heterotrimer, not COL1A2 alone. One other row abstract_insufficient. No database support.","key_references":[{"PMID":"16043429","why":"SPR binding of alpha1 I-domain to collagen"}],"covers":["LR000331","LR003837"]},"LR000340":{"pair":"COL3A1 -> DDR1","headline":"No paper in our evidence tests collagen III against DDR1; the pair rests on a solid-phase IntAct record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. IntAct lists Q08345 - P02461 as a solid phase assay, citing PMID:22483115 [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"COL3A1 flagged secreted, DDR1 receptor [flag].","caveats":"PMID:9659900 was judged pair_absent: collagen III never tested in that paper (full text). Two pair_absent, two review-only, three different_entity and two abstract-insufficient verdicts; no confirmation.","key_references":[],"covers":["LR000340","LR003846"]},"LR011131":{"pair":"COL4A1 -> CD44","headline":"Weak support: a gastric cancer abstract reports COL4A1 binding macrophage CD44/IL7R.","interaction_type":"functional only","direction_and_effect":"CAF-derived COL4A1 bound macrophage CD44/IL7R to drive M2-like polarization and suppress CD8 T-cell function; the database record is labelled stimulatory [PMID:41423274].","molecular_requirements":"The abstract names CD44 together with IL7R; whether CD44 alone suffices is not reported in our evidence [PMID:41423274].","affinity_potency":[],"species_and_systems":"Human gastric cancer tissue (CAFs and macrophages), with in vitro and in vivo experiments [PMID:41423274].","localisation_and_range":"Ligand flagged secreted [flag]; CD44 is flagged both transmembrane and secreted [flag]. The paper describes CAF-secreted COL4A1 acting on macrophages [PMID:41423274].","caveats":"Abstract only, a single paper, and the 'bound' wording is a summary statement; no binding assay details are visible. Several other judged papers were not usable (abstract_insufficient or different entity). No affinity reported.","key_references":[{"PMID":"41423274","why":"CD146+ CAF COL4A1 bound macrophage CD44/IL7R in gastric cancer"}],"covers":["LR011131"]},"LR011023":{"pair":"COL6A1 -> ITGA3:ITGB1","headline":"Weak: one abstract reports COL6A1 binding ITGB1 in glioblastoma; the alpha subunit is not named.","interaction_type":"functional only","direction_and_effect":"COL6A1 is bound to ITGB1 on endothelial cells, disrupting tight junctions via UBD-mediated claudin-5 degradation [PMID:41297453].","molecular_requirements":"The paper names only ITGB1, not the alpha partner, so ITGA3:ITGB1 is not distinguished from other beta1 heterodimers [PMID:41297453].","affinity_potency":[],"species_and_systems":"Human patient-derived glioblastoma organoids and endothelial cells [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the binding wording is an abstract statement. No affinity reported. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"41297453","why":"COL6A1 binds endothelial ITGB1 in TMZ-resistant glioblastoma"}],"covers":["LR011023"]},"LR011140":{"pair":"COL6A3 -> CD44","headline":"COL6A3 fragment endotrophin is reported to act on CD44 in hepatocellular carcinoma; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"The COL6A3 cleavage fragment endotrophin (ETP) was identified as a CD44 ligand by proximity labelling; ETP binding to CD44 activated STAT3 signaling, promoting EMT, proliferation and sorafenib resistance [PMID:41671381]. CD44 knockout, STAT3 inhibition or CD44 binding-deficient ETP mutants suppressed malignant phenotypes in vitro [PMID:41671381].","molecular_requirements":"The acting form is the COL6A3 cleavage fragment endotrophin, not full-length COL6A3 [PMID:41671381]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"HCC cells in vitro; in vivo, mice with Col6a3 and Cd44 dual knockout in a diethylnitrosamine plus high-fat diet model reduced tumor burden [PMID:41671381].","localisation_and_range":"Ligand flagged secreted; CD44 flagged secreted, receptor and transmembrane [flag]. Hepatic stellate cell-derived ETP targeted CD44+ tumor cells (paracrine) [PMID:41671381].","caveats":"Abstract only; no affinity reported. Assay class is functional_in_vitro. Four other papers judged abstract-insufficient.","key_references":[{"PMID":"41671381","why":"ETP binds CD44 and activates STAT3 in HCC"}],"covers":["LR011140"]},"LR011230":{"pair":"CRH -> MC2R","headline":"CRH to MC2R rests on a single GtoPdb agonist record; no curator-confirmed paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CRH as an agonist of MC2R, with no affinity value given [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"CRH is flagged secreted and MC2R a receptor [flag].","caveats":"No confirmed papers. The papers judged were insufficient from their abstracts or concerned a different entity, so this is database assertion only and should be treated as unverified.","key_references":[],"covers":["LR011230"]},"LR000403":{"pair":"CXCL13 -> CXCR3","headline":"One abstract-only 2001 paper reports CXCL13 binding and activating human CXCR3 with unusual pharmacology; CXCR5 is its conventional receptor.","interaction_type":"direct binding","direction_and_effect":"Human CXCL13 (BCA-1) competed with radiolabelled IP-10 for binding to human CXCR3, drove chemotaxis of CXCR3 transfectants (blocked by anti-CXCR3 antibody) and stimulated GTP gamma S binding [PMID:11554781]. It induced no calcium flux and attenuated the IP-10-induced calcium flux, suggesting biased or partial agonism [PMID:11554781].","molecular_requirements":"Not reported in our evidence; effects were shown in CXCR3-transfected cells.","affinity_potency":[],"species_and_systems":"Human CXCL13 on human CXCR3 expressed in Ba/F3 and 293EBNA cell lines [PMID:11554781]. The mouse pair is projected from human evidence, not tested.","localisation_and_range":"CXCL13 is flagged secreted [flag]; soluble ligand, cell-surface GPCR.","caveats":"Single paper, abstract only; no affinity value reported in our evidence. Calcium response is absent and IP-10 signalling is dampened, so effect is mixed. The abstract names CXCR5 as the previously known receptor for CXCL13 [PMID:11554781]. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"11554781","why":"Competition binding, chemotaxis and GTP gamma S data for CXCL13 on CXCR3"}],"covers":["LR000403","LR003908"]},"LR000412":{"pair":"CXCL3 -> CXCR2","headline":"Well supported agonist: potent signalling at human CXCR2 in transfectants, GtoPdb agonist record, UniProt high-affinity statement and structures.","interaction_type":"direct binding","direction_and_effect":"Agonist at IL8RB (CXCR2); the GROgamma/CXCL3 EC50 was 1 nM in calcium flux [PMID:8702798]. CXCL3-induced ASMC migration used CXCR1 and CXCR2 [PMID:23904157]. GtoPdb: full agonist [DB:GtoPdb]. UniProt for CXCR2 says it also binds CXCL3 with high affinity [DB:UniProt].","molecular_requirements":"No co-receptor requirement reported. PDB 8XWF and 8XX3 contain a CXCL3 chain and a CXCR2 chain [DB:PDB 8XWF].","affinity_potency":[{"value":"EC50 1 nM","assay":"calcium flux, GROgamma at IL8RB","system":"HEK293 transfectants","cite":"PMID:8702798"},{"value":"pIC50 7.8 to 9.2","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in HEK293 cells and human primary ASMCs [PMID:8702798][PMID:23904157].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"All papers abstract-only. PMID:8550564 names GROalpha, not CXCL3, so it supports CXCL3 only by analogy. Ligand assignment of GROgamma to CXCL3 rests on aliasing.","key_references":[{"PMID":"8702798","why":"Potency and binding at IL8RB"},{"PMID":"23904157","why":"CXCL3 migration via CXCR1/CXCR2"},{"PMID":"8550564","why":"IL-8RB selectivity group"}],"covers":["LR000412"]},"LR000430":{"pair":"DEFB103B -> CCR6","headline":"Human CCR6 support is mostly indirect or database-level; direct binding was shown for murine defensins 2 and 3 with mouse CCR6.","interaction_type":"direct binding","direction_and_effect":"Murine beta-defensins 2 and 3 bound murine CCR6 and chemoattracted immature but not mature bone marrow-derived dendritic cells, like MIP-3alpha [PMID:11714836]. Reactome records bind human beta-defensins 1, 4A and 103 to CCR6 [DB:Reactome]. In the CCR2 paper, hBD3:Ig is described as able to bind human and mouse CCR6, as reported earlier [PMID:20483750].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The experimental evidence in the verified papers is in mouse (murine defensins, mouse CCR6) [PMID:11714836]; the human pair rests on Reactome and background statements [DB:Reactome][PMID:20483750].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Both papers were read as abstract (the second also as full text); the human DEFB103B-CCR6 result itself is not a primary result of either paper. The CCR2 paper treats the CCR6 binding as previous work [PMID:20483750]. No affinity reported.","key_references":[{"PMID":"11714836","why":"Murine beta-defensin 2/3 binding to murine CCR6"},{"PMID":"20483750","why":"Background that hBD3:Ig binds human and mouse CCR6"}],"covers":["LR000430"]},"LR002500":{"pair":"DSG1 -> DSC2","headline":"DSG1 -> DSC2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR002500"]},"LR011401":{"pair":"DSPP -> ITGAV:ITGB1","headline":"Database-asserted only (Reactome); no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records DSPP(463-1301) binding integrin alphaVbeta1 [DB:Reactome R-HSA-4086132].","molecular_requirements":"Receptor complex is alphaV with beta1; the cleaved DSPP(463-1301) form is the one in the record [DB:Reactome R-HSA-4086137].","affinity_potency":[],"species_and_systems":"Human; no experiments reported in our evidence.","localisation_and_range":"DSPP is flagged as secreted [flag]; the integrin is a membrane receptor [flag].","caveats":"No paper confirmed this pair; the papers judged were different_entity or abstract_insufficient. Support rests on a database record alone.","key_references":[],"covers":["LR011401"]},"LR000502":{"pair":"EFNA5 -> EPHA4","headline":"Ephrin-A5 binds and activates EphA4, supported by crystal structures and mouse cochlea genetics.","interaction_type":"direct binding","direction_and_effect":"EphA4 is activated by both A- and B-class ephrins; crystal structures of the EphA4 ectodomain with ephrin-A5 show ligand binding induces conformational changes [PMID:23959867]. Complementary ephrin-A5 and EphA4 expression controls afferent fibre targeting in mouse cochlea; loss of either causes overshooting [PMID:23385583]. Ephrin-A5 Fc binds most EphA receptors with high apparent affinity [PMID:22568954].","molecular_requirements":"An EphA4 ligand-binding-domain interaction with its own fibronectin domain matters for efficient activation [PMID:23959867].","affinity_potency":[],"species_and_systems":"Human structures [PMID:23959867]; mouse in vivo [PMID:23385583]; ELISA, species unspecified [PMID:22568954]. Mouse pair listed as direct.","localisation_and_range":"Both flagged membrane-bound [flag].","caveats":"Mostly abstract-only reads; 22568954 was a browser read with unverifiable quote. IntAct and PDB records exist [DB:PDB 4BK5].","key_references":[{"PMID":"23959867","why":"EphA4-ephrin-A5 crystal structures"},{"PMID":"23385583","why":"Ephrin-A5/EphA4 repulsion in cochlear afferent targeting"},{"PMID":"22568954","why":"ELISA across EphA receptors"}],"covers":["LR000502","LR003993"]},"LR000511":{"pair":"EFNB1 -> EPHB3","headline":"No verified paper; support is UniProt text and an IntAct co-immunoprecipitation.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ephrin-B1 can also bind EPHB2 and EPHB3 [DB:UniProt]; effect annotated stimulatory.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct association by anti-tag co-immunoprecipitation (PMID 33961781); species not given [DB:IntAct]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Six judged papers were review_only; none confirmed. Rests on database records alone [DB:UniProt] [DB:IntAct].","key_references":[],"covers":["LR000511","LR004002"]},"LR004003":{"pair":"EFNB1 -> EPHB4","headline":"Single functional mouse paper: EFNB1 promotes IL-21 in T follicular helper cells mainly through EPHB4; no binding data.","interaction_type":"functional only","direction_and_effect":"EFNB1 promoted interleukin-21 production from germinal-centre TFH cells by signalling predominantly through EPHB4; it also inhibited T-B adhesion through EPHB6 [PMID:28408722].","molecular_requirements":"Receptor usage is context-split: EPHB4 for IL-21, EPHB6 for repulsion [PMID:28408722].","affinity_potency":[],"species_and_systems":"Mouse germinal-centre TFH cells; the human pair is ortholog-inferred [PMID:28408722].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Abstract only; one paper; no binding or affinity data. 'Predominantly' implies other receptors may contribute [PMID:28408722].","key_references":[{"PMID":"28408722","why":"EFNB1 acts via EPHB4 to promote IL-21 in GC TFH cells"}],"covers":["LR000512","LR004003"]},"LR000520":{"pair":"EFNB2 -> EPHB3","headline":"No verified paper; support is UniProt text and IntAct co-immunoprecipitations.","interaction_type":"database-asserted only","direction_and_effect":"UniProt: forward and reverse signalling through the EFNB2/EPHB3 complex regulate migration and adhesion of cells that tubularize the urethra and septate the cloaca [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct anti-tag co-immunoprecipitation records (PMIDs 28514442, 33961781); species not given [DB:IntAct]. Pair listed for human (ortholog-inferred) and mouse.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Six judged papers were review_only; none confirmed. Rests on database records alone.","key_references":[],"covers":["LR000520","LR004011"]},"LR004012":{"pair":"EFNB2 -> EPHB4","headline":"Best supported of this batch: sub-nanomolar binding, structure, and functional data in several systems.","interaction_type":"direct binding","direction_and_effect":"Ephrin-B2 expressing COS-7 cells induced tyrosine phosphorylation of Htk in 3T3 cells [PMID:7534404]. Ephrin-B2 stromal cells made EphB4+ progenitors detach and differentiate to erythroid cells [PMID:12051776]. Coexpressed (cis) ephrin-B2 inhibits EphB4 in cancer cells [PMID:24348920]. EphB4-Fc activation moved ephrinB2 to endothelial junctions [PMID:16357318].","molecular_requirements":"Trans activation needs ephrin-B2 on a neighbouring cell; cis coexpression attenuates it [PMID:24348920].","affinity_potency":[{"value":"Kd 535 pM","assay":"binding competition, Htk-Fc to Htk ligand","system":"ligand expression-cloned from a murine kidney mesangial cell line","cite":"PMID:7534404"}],"species_and_systems":"Mixed: murine-derived ligand [PMID:7534404], human umbilical cord blood cells [PMID:12051776], cultured endothelial cells [PMID:16357318]. Structure PDB 2HLE [DB:PDB 2HLE]; BioGRID and IntAct SPR records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Ten confirmed rows; five shown. The Kd paper does not name ephrin-B2 in its abstract (curator identification). ELISA quote was browser-read and unverified [PMID:22568954].","key_references":[{"PMID":"7534404","why":"Ligand cloned; Kd 535 pM; receptor phosphorylation"},{"PMID":"24348920","why":"cis inhibition of EphB4 by ephrin-B2"},{"PMID":"12051776","why":"Ephrin-B2 stroma drives EphB4+ erythroid differentiation"}],"covers":["LR000521","LR004012"]},"LR004030":{"pair":"F10 -> ITGAM","headline":"Factor X binds Mac-1 (ITGAM) on stimulated human monocytes with Kd 21.8-44.9 nM; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"125I-factor X bound saturably to ADP- or ionomycin-stimulated human monocytes and was cross-linked to its receptor, immunoprecipitated by anti-alpha subunit Mac-1 antibody OKM10 [PMID:2835359]. Direction effect not reported.","molecular_requirements":"Binding requires Ca2+ and stimulation of monocytes [PMID:2835359]. Alpha chain antibody pulls down the complex; the beta chain role is not reported in our evidence.","affinity_potency":[{"value":"Kd 21.8-44.9 nM","assay":"saturable 125I-factor X binding","system":"ADP- or ionomycin-stimulated human monocytes","cite":"PMID:2835359"}],"species_and_systems":"Human factor X and human monocytes [PMID:2835359]. Mouse pair is projected from human evidence [flag].","localisation_and_range":"F10 flagged secreted; cell-surface binding on monocytes [flag; PMID:2835359].","caveats":"Single 1988 abstract; evidence is for the Mac-1 heterodimer, so the alpha chain alone is not shown to suffice.","key_references":[{"PMID":"2835359","why":"Saturable factor X binding to Mac-1 on monocytes, Kd 21.8-44.9 nM"}],"covers":["LR000539","LR004030"]},"LR000610":{"pair":"FGF2 -> FGFR3","headline":"FGF2 binds FGFR3 poorly yet activates it; evidence is mixed and mostly abstract-level.","interaction_type":"direct binding","direction_and_effect":"FGFR3 bound FGF8 and FGF9 well but FGF2 poorly [PMID:10574949]. Even so, fgf2 bound to FGFR3c produced higher activation-loop tyrosine phosphorylation than fgf1 despite lower binding strength [PMID:21894939]. FGF2 was reported to prefer c splice forms in BaF3 assays [PMID:8663044].","molecular_requirements":"Splice form FGFR3c was studied; the activity tracks the c form [PMID:21894939][PMID:8663044]. Heparin requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; HEK 293T cells expressing FGFR3c with ligand over 5 ng/ml to 5000 ng/ml [PMID:21894939]; soluble FGFR3 binding domain [PMID:10574949]. IntAct surface plasmon resonance [DB:IntAct].","localisation_and_range":"FGF2 annotated secreted, FGFR3 transmembrane [flag].","caveats":"Binding is weak relative to FGFR1 [PMID:10574949] and to fgf1 [PMID:21894939], so FGFR3 may be a low-affinity partner. Two of three papers abstract only. No affinity value in our evidence.","key_references":[{"PMID":"21894939","why":"FGF2 vs FGF1 on FGFR3c: weaker binding, higher phosphorylation"},{"PMID":"10574949","why":"FGFR3 binds FGF2 poorly"}],"covers":["LR000610","LR004094"]},"LR004102":{"pair":"FGF2 -> SDC4","headline":"FGF2 binds syndecan-4 (ryudocan) via heparan sulfate chains, with Kd 0.50 nM for purified ryudocan; several supporting papers.","interaction_type":"direct binding","direction_and_effect":"bFGF bound only HS chains of syndecan-1 and -4 ectodomains by BIAcore [PMID:15226297]. Purified human ryudocan bound bFGF, midkine and TFPI via HS chains in a solid-phase assay [PMID:8621465]. Cotransfected syndecan-4 with FGFR1 increased specific 125I-bFGF binding two- to three-fold in K562 cells [PMID:8609172]. BioGRID lists a co-purification record [DB:BioGRID].","molecular_requirements":"HS chains mediate binding; heparitinase abolished it, chondroitin ABC lyase did not [PMID:8621465]. Syndecan-4 supports FGF2-FGFR1 complex formation in K562 cells [PMID:8609172].","affinity_potency":[{"value":"0.50 nM","assay":"apparent dissociation constant, solid-phase binding of bFGF to purified ryudocan","system":"human ryudocan from EAhy926 cells","cite":"PMID:8621465"}],"species_and_systems":"Murine mammary syndecan ectodomains [PMID:15226297]; human EAhy926 ryudocan [PMID:8621465]; human K562 cells [PMID:8609172].","localisation_and_range":"SDC4 is flagged as a receptor and FGF2 secreted [flag]; ryudocan is a cell-surface proteoglycan [PMID:8621465].","caveats":"HS-chain binding is not specific to syndecan-4; the Kd comes from an abstract-only paper. One further paper was abstract_insufficient and one pending.","key_references":[{"PMID":"8621465","why":"Ryudocan binds bFGF with Kd 0.50 nM via HS"},{"PMID":"15226297","why":"BIAcore: bFGF binds HS chains of SDC4"},{"PMID":"8609172","why":"Syndecan-4 increases FGF2 binding to FGFR1"}],"covers":["LR000618","LR004102"]},"LR005899":{"pair":"FGF2 -> TGFBR3","headline":"TGFBR3 binds FGF2 and promotes FGF2-driven neuronal differentiation of neuroblastoma cells; one abstract-only paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"T\u03b2RIII bound FGF2 and exogenous FGFR1, promoting neuronal differentiation of neuroblastoma cells; T\u03b2RIII and FGF2 cooperated to induce Id1 expression via Erk MAPK [PMID:24216509]. The authors describe a coreceptor function. Reactome has a FGF2:TGFBR3 complex and binding reaction [DB:Reactome].","molecular_requirements":"T\u03b2RIII acts with FGFR1 as a coreceptor [PMID:24216509]. Whether TGFBR3 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells and in vivo tumour models; ligand and receptor recorded as human [PMID:24216509]. Mouse pair is ortholog-inferred.","localisation_and_range":"TGFBR3 is flagged transmembrane [flag].","caveats":"Single paper read as abstract only; no affinity is given. Reactome cites the same paper and an additional PMID not in our papers [DB:Reactome].","key_references":[{"PMID":"24216509","why":"T\u03b2RIII binds FGF2 and acts as coreceptor in neuroblastoma differentiation"}],"covers":["LR002633","LR005899"]},"LR004111":{"pair":"FGF5 -> FGFR2","headline":"FGF5 binds and activates FGFR2: nanomolar KD with recombinant human proteins and Co-IP in nasopharyngeal carcinoma cells.","interaction_type":"direct binding","direction_and_effect":"Recombinant human FGF-5 bound and induced autophosphorylation of FGFR2 [PMID:8386828]. In NPC cells, CAF-secreted FGF5 bound FGFR2 (Co-IP) and activated Keap1/Nrf2/HO-1 signalling, inhibiting cisplatin-induced ferroptosis [PMID:38637504]. FGF5 bound FGFR2 more tightly than other FGFRs in NPC tissues [PMID:38637504].","molecular_requirements":"Heparin was present in the recombinant activity assays [PMID:8386828]. Other requirements are not reported in our evidence.","affinity_potency":[{"value":"KD between 0.5 and 1.5 x 10(-9) M","assay":"competition binding","system":"recombinant human FGF-5 with human FGFR-2","cite":"PMID:8386828"}],"species_and_systems":"Human NPC cell lines (HK1, C666-1), patient tissues and a nude-mouse xenograft with recombinant FGF5 [PMID:38637504]; human recombinant proteins [PMID:8386828]; BaF3 with unspecified species [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"FGF5 is a secreted factor (CAF-derived) [PMID:38637504] and flagged secreted [flag]; FGFR2 is a membrane receptor.","caveats":"The authors note it is uninvestigated whether FGF5/FGFR2 activates Keap1/Nrf2/HO-1 directly [PMID:38637504]. The KD range is shared with FGFR1 and from an abstract-only read.","key_references":[{"PMID":"38637504","why":"Co-IP and functional FGF5/FGFR2 axis in NPC"},{"PMID":"8386828","why":"KD and autophosphorylation of FGFR2"},{"PMID":"8663044","why":"BaF3 specificity survey"}],"covers":["LR000627","LR004111"]},"LR004120":{"pair":"FGF7 -> NRP1","headline":"FGF7 binds immobilised NRP1 strongly in a biosensor; heparin-dependent and functional relevance not shown.","interaction_type":"direct binding","direction_and_effect":"Strong binding to Npn-1 was observed with the four FGFs tested, including FGF-7 [PMID:15695515]. No FGF7 functional effect is reported in our evidence.","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site [PMID:15695515].","affinity_potency":[],"species_and_systems":"Optical biosensor with low-density immobilised Npn-1; human proteins [PMID:15695515]. Both interactions are ortholog-inferred.","localisation_and_range":"NRP1 is flagged as a transmembrane receptor with a secreted form [flag]; FGF7 localisation is not reported in our evidence.","caveats":"FGF-2 and FGF-4, not FGF-7, were additionally confirmed in a solution pull-down [PMID:15695515]. Binding is likely electrostatic rather than a specific interface; no kinetics for FGF7.","key_references":[{"PMID":"15695515","why":"Biosensor binding of FGF-7 to Npn-1"}],"covers":["LR000636","LR004120"]},"LR007969":{"pair":"FGFR4 -> TGFBR3","headline":"Supported only by one IntAct SPR record; no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists surface plasmon resonance, linked to PMID:35922511 [DB:IntAct]; species not given.","localisation_and_range":"Both are flagged transmembrane [flag]; classed Receptor-Receptor.","caveats":"No paper was judged for this pair; the single database record has not been curator-verified. Whether FGFR4 acts as a ligand here is unknown.","key_references":[],"covers":["LR007969"]},"LR012112":{"pair":"FST -> INHBA:INHBB","headline":"Database-level support for follistatin binding activin subunits; the INHBA:INHBB heterodimer (activin AB) is not specifically shown.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records follistatin binding activin [DB:Reactome R-HSA-2473184]; UniProt lists INHBA and INHBB as interacting with FST [DB:UniProt]. Inhibitory flag [flag].","molecular_requirements":"Structures cover INHBA (PDB 2B0U, 2P6A) and INHBB (PDB 9Z3T) [DB:PDB 2B0U, DB:PDB 9Z3T]; a heterodimer structure is not reported in our evidence.","affinity_potency":[],"species_and_systems":"not reported in our evidence.","localisation_and_range":"Receptor-side flagged secreted [flag].","caveats":"No verified papers (three pending). Evidence is for homodimeric activins, extrapolated to the AB heterodimer.","key_references":[],"covers":["LR012112"]},"LR011212":{"pair":"GDF1 -> BMPR1B","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at BMPR1B [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. No papers were judged. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR011212"]},"LR000700":{"pair":"GDF5 -> BMPR2","headline":"GDF5 binds the type II receptor BMPR-II, shown in two abstract-level papers and database records; BMPR-II works with BMPR-IB.","interaction_type":"direct binding","direction_and_effect":"GDF-5 bound BMPR-II in transfected COS-1 cells, and 125I-GDF-5 bound BMPR-IB and BMPR-II in non-transfected cells [PMID:8702914]. CDMP-1 and CDMP-2 had affinity for BMPR-IB and BMPR-II [PMID:9525338]. Signalling is stimulatory, with BMPR-IB transducing a transcriptional signal in the presence of BMPR-II [PMID:8702914] [PMID:9525338].","molecular_requirements":"BMPR-II acts as a type II partner of BMPR-IB; ActR-II and ActR-IIB also bound GDF-5 [PMID:8702914]. Whether BMPR-II alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat ROB-C26 cells and COS-1 transfectants [PMID:8702914]; ATDC5, ROB-C26, MC3T3-E1, primary chondrocytes [PMID:9525338]. The human pair has direct records; the mouse pair is ortholog-inferred. Database records: BioGRID reconstituted complex [DB:BioGRID], IntAct SPR [DB:IntAct], UniProt subunit note [DB:UniProt].","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"Both papers were read as abstracts only. One further paper was judged a different entity and one is pending. No affinity is reported for BMPR-II in our evidence.","key_references":[{"PMID":"8702914","why":"GDF-5 binds BMPR-II and cooperates with BMPR-IB"},{"PMID":"9525338","why":"Independent binding and reporter evidence"}],"covers":["LR000700","LR004184"]},"LR011221":{"pair":"GDF7 -> TGFBR1","headline":"GDF7 -> TGFBR1 rests on a GtoPdb agonist record alone; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records the interaction as Agonist, action Agonist, with no affinity units [DB:GtoPdb]. No curator-verified paper supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Support is a database assertion only. One paper was judged abstract-insufficient, so it gave no confirmation. The receptor is TGFBR1, a TGF-beta branch type I receptor name, while our papers show GDF7 using BMP-branch receptors.","key_references":[],"covers":["LR011221"]},"LR004201":{"pair":"GHRL -> GPR39","headline":"Only obestatin (a different peptide from the ghrelin gene), not ghrelin, was reported to bind GPR39, and that is an abstract-only claim.","interaction_type":"direct binding","direction_and_effect":"The abstract states that obestatin, isolated from rat stomach, bound the orphan receptor GPR39 and that the two peptides activate distinct receptors [PMID:16284174].","molecular_requirements":"Not reported in our evidence beyond the single receptor.","affinity_potency":[],"species_and_systems":"Rat peptide and receptor [PMID:16284174].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"The ligand shown is obestatin, not mature ghrelin; curator notes say the pairing was later contested and recommend downweighting. Abstract only; no affinity; no database support.","key_references":[{"PMID":"16284174","why":"Obestatin reported to bind GPR39"}],"covers":["LR000718","LR004201"]},"LR004210":{"pair":"GRP -> GRPR","headline":"GRP is a well-supported high-affinity agonist of GRPR, shown by binding and functional assays in human cells.","interaction_type":"direct binding","direction_and_effect":"GRP is an agonist at the human GRP receptor: binding activates phospholipase C and raises [3H]inositol phosphate [PMID:7838118]. GRP is the natural GRPR ligand, with >650-fold higher affinity than for hNMB receptors [PMID:21729729]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond receptor and peptide; GRP(1-27) was used in the full-text study [PMID:21729729].","affinity_potency":[{"value":"IC50 0.17\u20130.19 nM","assay":"radioligand competition binding","system":"human GRPR in Balb 3T3 transfectants and native HuTu-80 cells","cite":"PMID:21729729"},{"value":"EC50 13.6 nM","assay":"[3H]inositol phosphate generation","system":"human GRPR in stably transfected BALB/3T3 cells","cite":"PMID:7838118"}],"species_and_systems":"Human receptors in transfected and native cell lines [PMID:7838118] [PMID:21729729]. Rat GRPR pharmacology did not correlate with human (r=0.131), so rat data should not be extrapolated [PMID:21729729]. Mouse pair is ortholog-inferred.","localisation_and_range":"GRP is flagged secreted; GRPR is flagged as a transmembrane receptor [flag].","caveats":"One of the confirmed papers uses GRP-GRPR only as a reference system for antagonist work [PMID:19463875]. Several papers were read as abstracts only.","key_references":[{"PMID":"21729729","why":"GRP IC50 0.17-0.19 nM at human GRPR"},{"PMID":"7838118","why":"Cloned human GRPR, GRP potency and PLC activation"},{"PMID":"19463875","why":"Human bombesin receptor antagonist pharmacology"}],"covers":["LR000728","LR004210"]},"LR006799":{"pair":"HBB -> FPR1","headline":"Beta-hemoglobin fragment spinorphin antagonises FPR1 in neutrophil assays; GtoPdb lists it as an antagonist.","interaction_type":"functional only","direction_and_effect":"Spinorphin (LVV-hemorphin-4, a peptide matching a region of beta-hemoglobin) blocked fMLF-induced neutrophil chemotaxis, and GtoPdb records it as an antagonist at FPR1 [PMID:11714831][DB:GtoPdb]. It also induced calcium flux through FPR, so it behaved as a calcium-mobilising agonist but a weak chemotactic agonist [PMID:11714831].","molecular_requirements":"The active ligand is the spinorphin fragment, not intact HBB [PMID:11714831]. Spinorphin did not act on FPR2-expressing cells [PMID:11714831].","affinity_potency":[{"value":"pIC50 4.3","assay":"antagonism of fMLF response","system":"phagocytes","cite":"PMID:11714831"}],"species_and_systems":"Mouse neutrophils (wild-type and FPR-deficient) and HEK293 cells transfected with mouse FPR; curator metadata lists bovine ligand and human receptor [PMID:11714831].","localisation_and_range":"Not reported in our evidence; no secretion flag on the HBB entity [flag].","caveats":"Only the abstract was read. Evidence is functional, not binding. The pIC50 is from the curator record; the work used mouse FPR, so species of the 4.3 value is unclear. A second GtoPdb PMID (1373134) is not among the reviewed papers [DB:GtoPdb].","key_references":[{"PMID":"11714831","why":"Spinorphin acts on FPR and blocks fMLF chemotaxis"}],"covers":["LR006799"]},"LR011500":{"pair":"HLA-F -> CD8A","headline":"Weak evidence: one Chinese-language abstract reports recombinant HLA-F interacting with CD8alpha homodimers by gel filtration and native PAGE.","interaction_type":"direct binding","direction_and_effect":"HLA-F interacts with CD8alphaalpha in refolded recombinant protein assays; authors suggest it may affect CD8alphaalpha binding to other MHC molecules [PMID:22260070]. Direction and signalling effect not reported in our evidence.","molecular_requirements":"CD8alpha homodimer (CD8alphaalpha) was used [PMID:22260070].","affinity_potency":[],"species_and_systems":"E. coli-expressed, refolded human proteins in vitro; no cells [PMID:22260070].","localisation_and_range":"Not reported in our evidence; CD8A flagged secreted and transmembrane, HLA-F transmembrane [flag]. The interaction class is Receptor-Receptor [flag].","caveats":"Read as abstract only; gel-filtration and native-PAGE only, no affinity. Two other judged rows were abstract_insufficient and two different_entity, so no further support.","key_references":[{"PMID":"22260070","why":"recombinant HLA-F and CD8alphaalpha interact by gel filtration/native PAGE"}],"covers":["LR011500"]},"LR007996":{"pair":"HLA-F -> VSIR","headline":"HLA-F reported as a direct ligand of VISTA (VSIR) from a large recombinant interaction screen; single paper.","interaction_type":"direct binding","direction_and_effect":"The screen identified HLA-E and HLA-F as endogenous non-tumour ligands for the immune checkpoint receptor VISTA [PMID:35922511]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant proteins [PMID:35922511].","localisation_and_range":"HLA-F flagged transmembrane, VSIR transmembrane [flag].","caveats":"Single study; no pair-specific affinity in excerpts; HLA-G was probably not a ligand [PMID:35922511].","key_references":[{"PMID":"35922511","why":"screen discovering HLA-E/HLA-F as VISTA ligands"}],"covers":["LR007996"]},"LR005989":{"pair":"HMGB1 -> TREM1","headline":"One recent paper reports HMGB1 binding TREM-1 in solution and on monocytes, with activation; no Kd reported.","interaction_type":"direct binding","direction_and_effect":"HMGB1 binds TREM-1 at high affinity in solution and on the cell surface; binding causes lymphocytes to release IL-2, IL-1b, IL-6, TNF and Ifny, and cytotoxic lymphocytes capable of lysing HLA-negative tumour cells appear in PBMC [PMID:38203798]. Release of soluble TREM-1 from monocytes rises dose-dependently with HMGB1 [PMID:38203798]. UniProt lists HMGB1 among TREM1 activating ligands [DB:UniProt].","molecular_requirements":"HMGB1 appears to bind the TREM-1 monomer (about 52 kDa cross-linked complex, an equimolar 27 + 26 kDa complex) [PMID:38203798]. The paper's text recalls that HMGB1 is considered to need co-activating molecules for TREM-1 activation (background, not tested here).","affinity_potency":[{"value":"I50 1 \u00b1 0.2 nM","assay":"half-maximal cytotoxicity of lymphocytes versus HMGB1 concentration (functional potency, not binding)","system":"human PBMC","cite":"PMID:38203798"}],"species_and_systems":"Human proteins and human PBMC/monocytes [PMID:38203798]. The mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged as secreted [flag]; the paper describes secretion during inflammation and binding to monocyte surface TREM-1 [PMID:38203798].","caveats":"Read as abstract plus excerpts; the high-affinity claim has no Kd in our evidence. Binding was shown by cross-linking, immunoprecipitation and confocal colocalisation.","key_references":[{"PMID":"38203798","why":"HMGB1 binds TREM-1 in solution and on monocytes and activates cytotoxic lymphocytes"}],"covers":["LR002741","LR005989"]},"LR005998":{"pair":"HSP90B1 -> SCARF1","headline":"gp96 is endocytosed via SREC-I (SCARF1) in transfected cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Ectopic SREC-I expression in CHO cells confers recognition and uptake of calreticulin and gp96; uptake is competed by fucoidin and acetylated LDL [PMID:15371419]. SREC-I overexpression in macrophages increases chaperone endocytosis [PMID:15371419].","molecular_requirements":"SREC-I acts in addition to scavenger receptor class A; not all AcLDL-binding scavenger receptors bind these chaperones [PMID:15371419].","affinity_potency":[],"species_and_systems":"CHO cells and macrophages; curated as human [PMID:15371419]. The mouse pair is listed without ortholog inference.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; the paper treats gp96 as an extracellular chaperone endocytosed by the receptor [PMID:15371419].","caveats":"Abstract-only reading; the evidence is uptake and competition, no Kd.","key_references":[{"PMID":"15371419","why":"SREC-I mediates endocytosis of calreticulin and gp96"}],"covers":["LR002750","LR005998"]},"LR006001":{"pair":"HSPA4 -> TLR4","headline":"Mouse-cell functional evidence (abstract only) for released Hsp70 acting via TLR4; one BioGRID pull-down record. Human pair is ortholog-projected.","interaction_type":"functional only","direction_and_effect":"Hsp70 released in membrane vesicles by mouse mesoangioblasts interacts in an autocrine manner with TLR4 and CD91 to stimulate migration [PMID:27925208].","molecular_requirements":"CD91 is co-named as an interacting receptor; whether TLR4 acts alone is not reported in our evidence [PMID:27925208].","affinity_potency":[],"species_and_systems":"Mouse mesoangioblasts in vitro [PMID:27925208]. BioGRID lists an HSPA4 - TLR4 Affinity Capture-Western record; its species and system are not reported in our evidence [DB:BioGRID].","localisation_and_range":"HSPA4 is flagged secreted [flag]; autocrine action after vesicle release is reported [PMID:27925208].","caveats":"Paper read as abstract only; no affinity. The paper's protein is called Hsp70. The BioGRID record is an affinity-capture result, which is weaker than direct binding.","key_references":[{"PMID":"27925208","why":"Autocrine Hsp70 via TLR4 and CD91 in mouse mesoangioblast migration"}],"covers":["LR002754","LR006001"]},"LR006010":{"pair":"IFNA1 -> CR2","headline":"Direct binding of IFN-alpha to CR2 by SPR and ELISA in one paper; unusual non-IFNAR receptor.","interaction_type":"direct binding","direction_and_effect":"CR2 binds IFN-alpha in the same affinity range as C3d/iC3b, EBV-gp350 and CD23. Anti-CR2 mAb 171 diminished IFN-alpha-responsive gene induction in human B cells [PMID:16785534]. The curator labelled it agonist.","molecular_requirements":"IFN-alpha binds CR2 short consensus repeat domains 1 and 2, the site used by the three other ligands [PMID:16785534].","affinity_potency":[],"species_and_systems":"Human proteins; SPR, ELISA and purified human peripheral blood B cells [PMID:16785534]. The mouse pair is ortholog-inferred.","localisation_and_range":"IFNA1 is flagged secreted and CR2 transmembrane [flag].","caveats":"Abstract only; the abstract says IFN-alpha generally, so IFNA1 specifically is an inference [PMID:16785534]. No numeric affinity reported. UniProt and BioGRID list the pair [DB:UniProt] [DB:BioGRID].","key_references":[{"PMID":"16785534","why":"SPR/ELISA binding of IFN-alpha to CR2 SCR1-2"}],"covers":["LR002763","LR006010"]},"LR005200":{"pair":"IFNE -> IFNAR2","headline":"IFNE signals through IFNAR2 in mouse, shown functionally; human pair is projected. No database records.","interaction_type":"functional only","direction_and_effect":"IFN-\u03b5 signalled via the Ifnar1 and Ifnar2 receptors to induce IFN-regulated genes, so it acts as a type I IFN agonist [PMID:23449591]. Ifn-\u03b5-deficient mice were more susceptible to HSV-2 and Chlamydia muridarum infection of the female reproductive tract [PMID:23449591].","molecular_requirements":"Both Ifnar1 and Ifnar2 are named as the signalling receptors [PMID:23449591]; whether one chain suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments; the human pair is ortholog-inferred, the mouse pair is not [PMID:23449591].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. The paper reports IFN-\u03b5 constitutively expressed by female reproductive tract epithelium and hormonally regulated [PMID:23449591].","caveats":"Evidence is functional (gene induction), not binding, and abstract-only. No direct binding or affinity data and no database records in our evidence.","key_references":[{"PMID":"23449591","why":"IFN-\u03b5 signals via Ifnar1/Ifnar2; knockout mice more infection-prone"}],"covers":["LR001852","LR005200"]},"LR008968":{"pair":"IL16 -> KCNJ10","headline":"Database-asserted only: a UniProt subunit note lists KCNJ10 as an IL16 isoform 1 interactor; no papers support a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. UniProt states that isoform 1 interacts with GRIN2D, KCNJ10, KCNJ15 and CACNA1C (By similarity) [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"UniProt annotation 'By similarity' only; no experiment species reported in our evidence [DB:UniProt].","localisation_and_range":"IL16 is annotated as secreted [flag]; no localisation annotation for the partner in our evidence.","caveats":"No curated paper evidence; the interaction was judged a different entity in our curation. The UniProt statement is inferred by similarity, not shown directly for this pair.","key_references":[],"covers":["LR008968"]},"LR004300":{"pair":"IL17A -> IL17RC","headline":"IL-17A binds IL-17RC in SPR with affinity comparable to IL-17F, as part of an IL-17RA/IL-17RC receptor; one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17A, IL-17F and the heterodimer bound IL-17RC with comparable affinities; IL-17A activity was inhibited by soluble IL-17RA rather than IL-17RC [PMID:18684971]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"IL-17RC functions as a receptor for IL17A and IL17F homodimers within a heterodimer with IL17RA, but UniProt also notes it may bind IL17A with high affinity without IL17RA [DB:UniProt]. PDB 7UWN and 7ZAN contain IL17RC and IL17RA chains [DB:PDB 7UWN].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and human bronchial epithelial cells [PMID:18684971]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17A annotated as secreted [flag]; IL-17RC annotated as a receptor [flag].","caveats":"Single paper, read as abstract only; no affinity values reported in the abstract [PMID:18684971].","key_references":[{"PMID":"18684971","why":"SPR binding of IL-17A, F and A/F to IL-17RC; receptor complex"}],"covers":["LR000870","LR004300"]},"LR011005":{"pair":"LAMB1 -> ITGA2:ITGB1","headline":"Complex row for laminin beta1 and integrin alpha2beta1; only a PDB and a similarity-based UniProt record, no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P07942 and a chain of P05556 [DB:PDB 7CEC]; UniProt notes ITGB1 interacts with LAMB1 (by similarity) [DB:UniProt].","molecular_requirements":"Receptor is the ITGA2:ITGB1 heterodimer per the entity record; the UniProt note concerns ITGB1 only.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA2:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Three papers are still pending, none judged. The UniProt statement is by similarity, and neither record tests ITGA2.","key_references":[],"covers":["LR011005"]},"LR006100":{"pair":"LAMB2 -> DAG1","headline":"Laminin beta2-containing laminins (laminin-11, merosin) bind alpha-dystroglycan in brain and nerve; chain-level, abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 preferentially bound brain alpha-dystroglycan over skeletal-muscle alpha-dystroglycan [PMID:16709410]. Peripheral-nerve alpha-dystroglycan binds laminin (A/B1/B2) and merosin (M/B1/B2) [PMID:7925941]. Annotated stimulatory.","molecular_requirements":"Binding depends on the alpha-dystroglycan form (brain glycoepitope) [PMID:16709410]; in nerve it is Ca2+-dependent and heparin-inhibitable [PMID:7925941]. LAMB2 was not tested alone, and only laminin-11 among the laminin-10/11 pair contains beta2.","affinity_potency":[],"species_and_systems":"Mammalian brain and peripheral nerve extracts; species not reported in our evidence. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LAMB2 is flagged secreted [flag] and DAG1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers are abstract-only reads on whole laminins; LAMB2 is inferred from laminin-11 and merosin composition. No affinity values reported.","key_references":[{"PMID":"16709410","why":"Laminin-10/11 binds brain alpha-dystroglycan"},{"PMID":"7925941","why":"Nerve alpha-dystroglycan binds laminin and merosin"}],"covers":["LR002866","LR006100"]},"LR011050":{"pair":"LAMB2 -> ITGA6:ITGB1","headline":"Database structure record only for LAMB2 with ITGA6:ITGB1; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"Only a PDB structure record supports this pair; direction and effect are not reported in our evidence.","molecular_requirements":"The record shows a structure with chains of P11047 and P23229 [DB:PDB 7CEC]; which subunits are required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Both judged papers were abstract_insufficient.","key_references":[],"covers":["LR011050"]},"LR001006":{"pair":"LAMB3 -> ITGA6","headline":"LAMB3 (in laminin-332) binds integrin alpha6beta1 at Kd 7.5 nM in recombinant assays; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha6beta1 in solid-phase assays [PMID:16413178]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"Binder tested is the alpha6beta1 heterodimer, ligand the assembled heterotrimer; ITGA6 alone and LAMB3 alone were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 7.5 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta1 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. One confirming paper; three others were abstract_insufficient.","key_references":[{"PMID":"16413178","why":"Kd for alpha6beta1 vs laminin-332"}],"covers":["LR001006","LR004424"]},"LR001015":{"pair":"LAMC2 -> ITGA6","headline":"Recombinant integrin alpha6beta1 binds laminin-332 (contains LAMC2) with Kd 7.5 nM; LAMC2 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha6beta1 bound laminin-332 in solid-phase assays [PMID:16413178]. Recorded effect: stimulatory [flag].","molecular_requirements":"The ligand tested is the assembled laminin-332 heterotrimer and the receptor the alpha6beta1 heterodimer; individual chains were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 7.5 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha6beta1 ectodomain","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"Chain-level assignment inferred from heterotrimer and heterodimer binding.","key_references":[{"PMID":"16413178","why":"Laminin isoform binding by recombinant integrins"}],"covers":["LR001015","LR004433"]},"LR001024":{"pair":"LHB -> LHCGR","headline":"LH (LHB subunit) binds and activates the LH receptor; supported by two abstract-read papers and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"LH binds the human LH receptor and stimulates cAMP production; it is an agonist [PMID:12727981]. LH and hCG displaced [125I]hCG binding [PMID:1922095]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"LH is a heterodimer of CGA with LHB, so LHB is only the beta chain of the active hormone (curator note) [PMID:12727981]. Deleting LHR exon 10 does not change LH binding affinity but impairs LH-induced cAMP production [PMID:12727981].","affinity_potency":[{"value":"ED50 4.8 ng/ml","assay":"125I-hCG displacement by LH","system":"human LH receptor in 293 cells","cite":"PMID:1922095"},{"value":"pIC50 9.899999618530273 to 10.899999618530273","assay":"GtoPdb affinity range (pIC50)","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human LH and human receptor in COS-7 and 293 cells [PMID:12727981][PMID:1922095].","localisation_and_range":"LHB is secreted and LHCGR is a transmembrane receptor [flag]; endocrine signalling is implied by the secreted flag only.","caveats":"Both papers read as abstracts only. The first paper's evidence sentence is general and the binding result is carried by the assay detail [PMID:12727981]. A third paper was judged abstract-insufficient. GtoPdb affinity is a range given for the hormone, not LHB alone.","key_references":[{"PMID":"1922095","why":"LH displaces hCG binding to human LH receptor, ED50 4.8 ng/ml"},{"PMID":"12727981","why":"LH and hCG bind LHR with similar affinity; exon 10 needed for LH activation"}],"covers":["LR001024"]},"LR001033":{"pair":"LPL -> LRP2","headline":"LPL binds purified human and rat gp330/LRP2 with nanomolar affinity in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Purified gp330 bound LPL with high affinity; binding was saturable, divalent-cation dependent and inhibited by heparin or RAP [PMID:7686151]. LPL promoted in vitro binding of 125I-lipoproteins to gp330 [PMID:7686151].","molecular_requirements":"Not reported in our evidence beyond cation dependence and inhibition by heparin or RAP [PMID:7686151].","affinity_potency":[{"value":"Kd = 6.1 nM","assay":"in vitro binding to purified receptor","system":"human gp330","cite":"PMID:7686151"},{"value":"2.7 nM","assay":"in vitro binding to purified receptor","system":"rat gp330","cite":"PMID:7686151"}],"species_and_systems":"Purified human and rat gp330 in vitro [PMID:7686151]. The mouse pair is ortholog-inferred.","localisation_and_range":"LPL is annotated secreted [flag]. gp330 is a cell-surface protein in clathrin-coated pits [PMID:7686151].","caveats":"Single paper, abstract only. Binding to purified protein; cellular function not shown in our evidence. gp330 did not bind alpha2-macroglobulin-protease complex or Pseudomonas exotoxin A [PMID:7686151].","key_references":[{"PMID":"7686151","why":"gp330 binds LPL with Kd 6.1 nM (human) and 2.7 nM (rat)"}],"covers":["LR001033","LR004447"]},"LR007978":{"pair":"LRPAP1 -> SORT1","headline":"Sortilin was purified from human brain by RAP affinity chromatography; the interaction rests on that paper plus SPR records.","interaction_type":"direct binding","direction_and_effect":"Gp95/sortilin was purified from human brain extracts by RAP affinity chromatography [PMID:9013611]. No effect direction is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human brain extracts [PMID:9013611]. IntAct holds SPR and cross-linking records [DB:IntAct] and BioGRID reconstituted complexes [DB:BioGRID].","localisation_and_range":"LRPAP1 is flagged secreted [flag]. The paper describes RAP as an ER/Golgi protein involved in receptor processing [PMID:9013611].","caveats":"Binding is by affinity purification only in this paper; RAP is a chaperone, so physiological relevance as an extracellular ligand is unclear. Abstract only; no affinity.","key_references":[{"PMID":"9013611","why":"Sortilin identified by RAP binding"}],"covers":["LR007978"]},"LR001051":{"pair":"MATN1 -> ITGA1","headline":"Matrilin-1 associates with the integrin alpha1 subunit in one abstract-only paper; support is thin.","interaction_type":"direct binding","direction_and_effect":"Antibody to integrin alpha1 co-precipitated 125I-CMP (matrilin-1) from MRC5 cell lysates and unlabeled CMP competed, indicating association with alpha1; antibody to alpha1 or beta1 abolished CMP-induced adhesion and spreading [PMID:10196235].","molecular_requirements":"Alpha1beta1 is implicated: alpha1 and beta1 antibodies blocked adhesion, while antibodies to alpha2, alpha3, alpha5, beta2, alpha5beta1 or alphaVbeta5 had little effect [PMID:10196235].","affinity_potency":[],"species_and_systems":"Rabbit chondrocytes and fibroblasts, human epiphyseal chondrocytes and MRC5 fibroblasts; binding shown in human MRC5 lysates [PMID:10196235]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"MATN1 is flagged secreted [flag]; used as a coating substrate, matrix-type adhesion.","caveats":"Single paper, abstract only; co-precipitation from lysate does not exclude indirect association. A BioGRID reconstituted-complex record cites the same paper [DB:BioGRID].","key_references":[{"PMID":"10196235","why":"matrilin-1 (CMP) adhesion and alpha1 co-precipitation"}],"covers":["LR001051","LR004464"]},"LR001060":{"pair":"MDK -> PTPRZ1","headline":"Midkine binds PTPRZ1 with high affinity in a solid-phase assay; a single abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Midkine binds PTPzeta (PTPRZ1) in a solid-phase binding assay, and the authors conclude PTPzeta is a common receptor for midkine and pleiotrophin [PMID:10212223]. Midkine's C-terminal half is fully active for binding; Arg78 mutation lost high-affinity binding and reduced neuronal migration induction [PMID:10212223].","molecular_requirements":"High-affinity binding depends on Arg78 of midkine, which is proposed to contact the chondroitin sulfate portion of PTPzeta; chondroitinase ABC-treated PTPzeta shows only low-affinity binding [PMID:10212223]. Reactome lists (PTN,MDK):PTPRZ complexes [DB:Reactome].","affinity_potency":[{"value":"Kd 0.58 nM (high-affinity site); 3.0 nM (low-affinity site)","assay":"solid-phase binding, Scatchard analysis","system":"human midkine, rat PTPzeta","cite":"PMID:10212223"}],"species_and_systems":"Human midkine with rat PTPzeta, recombinant/purified in vitro [PMID:10212223]. Human and mouse pairs are both projected from this evidence.","localisation_and_range":"PTPRZ1 is flagged both secreted and transmembrane, and midkine as secreted [flag]; range is not tested in our evidence.","caveats":"Only one paper, read as abstract only. Binding relies on chondroitin sulfate chains of the receptor, so core-protein-only binding is not shown. BioGRID lists a reconstituted complex [DB:BioGRID] and UniProt cites the same paper [DB:UniProt].","key_references":[{"PMID":"10212223","why":"Solid-phase binding with Scatchard Kd values and Arg78 requirement"}],"covers":["LR001060","LR004473"]},"LR011041":{"pair":"NCAM1 -> L1CAM","headline":"NCAM and L1 form a cis complex via L1 oligomannosidic carbohydrates; read from full text.","interaction_type":"direct binding","direction_and_effect":"L1 and NCAM bind each other via oligomannosidic carbohydrates on L1, not NCAM [PMID:8509458].","molecular_requirements":"Complex formation was inhibited by an anti-oligomannose mAb and by the oligosaccharides; the NCAM Ig-domain fragment, not the F3 fragment, bound oligomannosidic glycans [PMID:8509458].","affinity_potency":[],"species_and_systems":"Experimental species and cells are not reported in our evidence; Reactome lists L1:NCAM1 cis-interaction [DB:Reactome R-HSA-374576].","localisation_and_range":"Both flagged transmembrane [flag]; the paper describes a cis-association [PMID:8509458].","caveats":"Carbohydrate-mediated cis association, so direction is symmetric and expression on the same cell is needed. One other row was abstract_insufficient.","key_references":[{"PMID":"8509458","why":"L1-NCAM binding via oligomannosidic carbohydrates"}],"covers":["LR011041"]},"LR001105":{"pair":"NLGN2 -> NRXN1","headline":"Supported mainly by a general neurexin-binding paper and a mutation study; no NLGN2-specific affinity.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins in native and recombinant form [PMID:8576240]. Truncated NRXN1 and NRXN2 proteins failed to bind NLGN2 in cell binding assays and failed to promote synaptic differentiation [PMID:21424692].","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Human cell binding assays and neuron coculture (curator: human) [PMID:21424692]; species unspecified for 8576240. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Both papers abstract-only. The mutation paper shows loss of binding by truncated NRXN1, with NLGN2 binding by the wild type described only as 'established' [PMID:21424692]. The 8576240 sentence refers to beta-neurexins as a class. Further papers were abstract-insufficient or pending.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to beta-neurexins"},{"PMID":"21424692","why":"Truncated NRXN1 fails to bind NLGN2"}],"covers":["LR001105","LR004516"]},"LR001114":{"pair":"NMS -> NMUR2","headline":"Functionally supported agonist pair from one abstract-level rat paper, with a Reactome binding reaction and GtoPdb and UniProt records.","interaction_type":"functional only","direction_and_effect":"NMS is an agonist: it was purified from rat brain as an endogenous ligand of FM-4/TGR-1 (NMU receptors), and ICV NMS activates SCN neurons and shifts circadian phase in rats [PMID:15635449]. GtoPdb lists it as an agonist [DB:GtoPdb]; Reactome has 'NMUR2 binds neuromedin-S' [DB:Reactome R-HSA-981832].","molecular_requirements":"Not reported in our evidence beyond the receptor chain; a PDB structure with these chains exists [DB:PDB 7W57].","affinity_potency":[{"value":"pIC50 9.199999809265137","assay":"as recorded for the paper's curated affinity field","system":"rat","cite":"PMID:15635449"}],"species_and_systems":"Rat peptide and rat receptor [PMID:15635449]; human and mouse not directly tested in our evidence.","localisation_and_range":"NMS flagged secreted [flag]; the paper proposes autocrine and/or paracrine action [PMID:15635449].","caveats":"One paper, abstract only, naming the receptor only as FM-4/TGR-1 (NMU receptors); NMUR2-specific evidence otherwise rests on databases.","key_references":[{"PMID":"15635449","why":"Identification of NMS as endogenous NMU-receptor ligand"}],"covers":["LR001114","LR004525"]},"LR001123":{"pair":"NPB -> NPBWR2","headline":"NPB binds NPBWR2 (GPR8) with low nanomolar affinity in one human-receptor paper; shares affinity with NPBWR1.","interaction_type":"direct binding","direction_and_effect":"L7 and L7C peptides, which curators map to NPB, bound GPR8 with low nanomolar affinity and inhibited forskolin-stimulated cAMP via a pertussis toxin-sensitive mechanism [PMID:12401809]; GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"low nanomolar","assay":"binding assay","system":"CHO-K1 cells expressing GPR8","cite":"PMID:12401809"}],"species_and_systems":"Human receptors in CHO-K1 cells; abstract only [PMID:12401809].","localisation_and_range":"NPB is flagged secreted [flag].","caveats":"Single paper. NPB and NPW are essentially non-selective between GPR7 and GPR8 [PMID:12401809]. The paper's receptor name is GPR8, mapped to NPBWR2 by curators.","key_references":[{"PMID":"12401809","why":"NPB (L7) binding and signalling at GPR8"}],"covers":["LR001123"]},"LR001132":{"pair":"NPPB -> NPR3","headline":"BNP binds the NPR3 clearance receptor, supported by abstract-level binding studies and structures.","interaction_type":"direct binding","direction_and_effect":"Rat BNP-45 interacted preferentially with the C-receptor and bound with lower affinity than rANP to guanylate cyclase-linked receptors and C-receptor [PMID:7901875]. UniProt says BNP binds NPR3 [DB:UniProt].","molecular_requirements":"NPR-C binds hormone as a dimer (1:2 stoichiometry, per curator sentence) [PMID:11533490]; PDB has a BNP-NPR3 structure [DB:PDB 1YK1].","affinity_potency":[],"species_and_systems":"Rat kidney cortex and lung [PMID:7901875]; human, bovine and rat preparations [PMID:1309330]; human NPR-C structure [PMID:11533490]. Mouse pair is projected.","localisation_and_range":"BNP annotated secreted [flag].","caveats":"All papers read as abstracts. Binding-affinity rank order at the C-receptor was ANP greater than CNP greater than BNP in humans and rats [PMID:1309330]. PMID:11533490 abstract describes a CNP complex only. Two further judged papers were unresolvable or insufficient.","key_references":[{"PMID":"7901875","why":"Rat BNP binding and cross-linking to C-receptor"},{"PMID":"1309330","why":"C-receptor affinity rank order"},{"PMID":"11533490","why":"NPR-C structure"}],"covers":["LR001132","LR004542"]},"LR001141":{"pair":"NPY -> NPY1R","headline":"NPY is a well-supported agonist of NPY1R, with cryo-EM structure, many database records and one binding paper.","interaction_type":"direct binding","direction_and_effect":"NPY is an agonist of Y1. A cryo-EM structure of NPY-bound Y1 has been reported [PMID:35165283]; NPY displays highest affinities for Y1, Y2 and Y5 subtypes [PMID:15966750]; GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor needed according to the structure listing, with several PDB entries (7VGX, 7X9A, 8K6M, 8K6O) [DB:PDB 7VGX].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers [PMID:35165283][PMID:15966750]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY1R transmembrane [flag].","caveats":"Both papers were read as abstract only, and the structure abstract is truncated. The binding paper gives only a qualitative selectivity statement [PMID:15966750]. NPY also binds other Y receptors; no affinity number for Y1 appears in our evidence.","key_references":[{"PMID":"35165283","why":"Cryo-EM structure of NPY-bound Y1"},{"PMID":"15966750","why":"NPY highest affinities at Y1, Y2, Y5"}],"covers":["LR001141","LR004550"]},"LR003004":{"pair":"NRG1 -> ITGA6","headline":"Single abstract-level report that NRG1 binds integrin alpha6 (ITGA6); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003004","LR006228"]},"LR001150":{"pair":"NRG2 -> ERBB4","headline":"NRG2 activates ERBB4 (and ERBB3); supported by two 1997 abstract-level papers plus BioGRID and Reactome records.","interaction_type":"direct binding","direction_and_effect":"NRG2 acts as an agonist: its EGF-like domain binds ErbB3 and ErbB4 and NRG2 stimulates ErbB tyrosine phosphorylation [PMID:9168115]. Recombinant NRG2-beta activates only cell lines with ErbB3 and/or ErbB4 [PMID:9168114].","molecular_requirements":"ErbB2, ErbB3 and ErbB4 were all phosphorylated in cells expressing all three; with defined combinations only ErbB3 and/or ErbB4 lines responded, so ERBB4 alone as a single chain is not separately resolved in the abstracts [PMID:9168114]. Reactome lists NRG2 complexes with ERBB4 homodimers [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers (cell lines); adult rat tissues used for expression only [PMID:9168114]. The mouse pair is projected from human evidence.","localisation_and_range":"Annotated as secreted and transmembrane, so likely both a membrane-bound and a released form [flag]; not tested in the papers.","caveats":"Both papers were read as abstracts only. NRG2 elicits different ErbB phosphorylation profiles from NRG-1 [PMID:9168115]. No affinity reported. GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"9168115","why":"NRG2 EGF-like domain binds ErbB3 and ErbB4"},{"PMID":"9168114","why":"NRG2-beta activates only ErbB3/ErbB4-containing cells"}],"covers":["LR001150","LR004559"]},"LR003013":{"pair":"NRTN -> SDC3","headline":"Direct binding of matrix-immobilised NRTN to the heparan sulfate chains of syndecan-3, with RET-independent cell effects; one paper.","interaction_type":"direct binding","direction_and_effect":"Immobilised NRTN induced adherence and spreading of SHEP cells in an HSPG-dependent way; these cells do not express RET, so the effect is RET-independent [PMID:21200028]. Syndecan-3 may transduce GFL signals directly or act as a co-receptor presenting GFLs to RET [PMID:21200028].","molecular_requirements":"Binding is via the heparan sulfate chains of syndecan-3; heparinase III treatment inhibited GDNF-syndecan-3 binding and reduced cell adherence [PMID:21200028]. Src-family kinase activation is involved in spreading.","affinity_potency":[{"value":"Kd 10-50 nM","assay":"surface plasmon resonance, immobilised GFLs vs syndecan-3 ectodomain (reported for GDNF, NRTN, ARTN together)","system":"syndecan-3 purified from rat brain","cite":"PMID:21200028"}],"species_and_systems":"Rat brain syndecan-3 ectodomain by SPR; SHEP cell assays; human/mouse labels in the dossier come from curation. Mouse pair is ortholog-inferred.","localisation_and_range":"Syndecan-3 is a transmembrane proteoglycan; NRTN acted when matrix-immobilised, not soluble [PMID:21200028]. NRTN is flagged secreted [flag].","caveats":"Single paper, read as abstract by curators though full text was available. The effect applies to immobilised, not soluble, ligand. It is a heparan sulfate interaction, which may be shared with other HS-binding proteins.","key_references":[{"PMID":"21200028","why":"NRTN, GDNF and ARTN bind syndecan-3 HS chains; RET-independent cell spreading"}],"covers":["LR003013","LR006237"]},"LR003022":{"pair":"NRXN1 -> NLGN1","headline":"Classic direct binding of neurexin-1beta to neuroligin-1, Ca2+-dependent, supported by a cell-aggregation paper and BioGRID.","interaction_type":"direct binding","direction_and_effect":"Cells expressing neurexin 1beta aggregate only with cells expressing neuroligin 1; the two function as heterophilic cell adhesion molecules [PMID:9325340].","molecular_requirements":"Binding needs Ca2+ (half-maximal at 1-3 microM free Ca2+) and only neurexin 1beta lacking an insert in splice site 4 binds; aggregation was inhibited by soluble neurexin 1beta lacking the insert [PMID:9325340].","affinity_potency":[],"species_and_systems":"Detergent-solubilised neuroligins and transfected cell lines; species not stated in dossier. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both are transmembrane [flag]; trans-cellular adhesion. BioGRID lists reconstituted complexes [DB:BioGRID].","caveats":"Abstract-only read. No affinity value in our evidence.","key_references":[{"PMID":"9325340","why":"neurexin 1beta-neuroligin 1 Ca2+-dependent cell aggregation"}],"covers":["LR003022","LR006246"]},"LR003031":{"pair":"NRXN3 -> LRRTM2","headline":"LRRTM2 binds alpha- and beta-neurexins directly; the paper treats neurexins generically, so NRXN3 is inferred.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 directly binds alpha- and beta-neurexins and forms a trans cell-adhesion junction [PMID:20064387].","molecular_requirements":"Binding needs neurexins lacking an insert in splice site #4 and is Ca2+ dependent; all three alpha-neurexins appeared in the LRRTM2 affinity purification and all three beta-neurexins bound per the curator note [PMID:20064387].","affinity_potency":[],"species_and_systems":"Recombinant Ig-fusions in HEK293/HEK293T cells and rat brain affinity chromatography [PMID:20064387]. Both species rows are ortholog-inferred.","localisation_and_range":"Both partners are flagged as transmembrane, non-secreted [flag], so contact-dependent (juxtacrine/trans-synaptic) signalling is implied; the paper shows trans cell adhesion [PMID:20064387].","caveats":"Evidence sentence names neurexins generically; two other judged rows were a different entity.","key_references":[{"PMID":"20064387","why":"LRRTM2 binds alpha/beta-neurexins, trans adhesion"}],"covers":["LR003031","LR006255"]},"LR003040":{"pair":"NTN4 -> ITGB1","headline":"Netrin-4 binds alpha6beta1 integrin dose-dependently in endothelial cells; one abstract-only paper, no chain-specific data.","interaction_type":"direct binding","direction_and_effect":"Alpha6beta1 integrin binds netrin-4 in a dose-dependent manner; inhibiting alpha6 or beta1 suppresses netrin-4-induced endothelial migration, adhesion, focal adhesion contact and Src-family phosphorylation [PMID:21799154].","molecular_requirements":"The binding is to the alpha6beta1 heterodimer; both the alpha6 and beta1 subunits are needed for the functional effects [PMID:21799154]. Chain-specific binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial and lymphatic endothelial cells; species is not stated in the curation record [PMID:21799154]. Pair is ortholog-inferred for both species.","localisation_and_range":"Netrin-4 is flagged secreted [flag].","caveats":"Abstract only. The ITGB1 pair is a subunit of the complex; CCC tools scoring complexes need both integrin chains.","key_references":[{"PMID":"21799154","why":"Netrin-4 binds and activates endothelial alpha6beta1 integrin"}],"covers":["LR003040","LR006264"]},"LR001204":{"pair":"PENK -> MRGPRX1","headline":"Proenkephalin-derived peptides (BAM22 and BAM8-22) activate MRGPRX1; two abstract-only papers plus GtoPdb and PDB structures.","interaction_type":"direct binding","direction_and_effect":"BAM22 and fragments bind and activate the receptor family, full agonist [PMID:11850634]. BAM8-22 inhibited high-voltage-activated Ca2+ current in neurons expressing the human receptor, partly pertussis toxin sensitive [PMID:15163697]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The active ligands are processed fragments of PENK, not the full precursor [PMID:11850634] [PMID:15163697]. Receptor subunit or co-receptor needs not reported in our evidence.","affinity_potency":[{"value":"pKi 7.68","assay":"heterologous expression binding","system":"cloned SNSR family receptors","cite":"PMID:11850634"}],"species_and_systems":"Binding and activation in heterologous expression [PMID:11850634]; human receptor expressed in rat DRG, SCG and hippocampal neurons, with bovine-derived BAM8-22 [PMID:15163697]. Pair is human.","localisation_and_range":"PENK is flagged secreted [flag]. Receptor localisation in small sensory neurons is stated in the abstract [PMID:11850634].","caveats":"Both papers were read as abstracts only. The gene-level pair stands in for specific fragments. GtoPdb gives pEC50 5.3 to 7.8 [DB:GtoPdb]. PDB structures 8DWC, 8DWG, 8JGF and 8JGG contain chains of the two proteins [DB:PDB 8DWC].","key_references":[{"PMID":"11850634","why":"BAM22 binds and activates SNSR family"},{"PMID":"15163697","why":"BAM8-22 signalling via human receptor in neurons"}],"covers":["LR001204"]},"LR003103":{"pair":"PLA2G1B -> PLA2R1","headline":"No curated papers; support is UniProt statements that PLA2R1 binds sPLA2-IB.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states PLA2R1 acts as a receptor for sPLA2-IB/PLA2G1B but not sPLA2-IIA [DB:UniProt Q13018], and that binding can regulate podocyte survival and glomerular homeostasis [DB:UniProt P04054][DB:UniProt Q13018].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental species or system in our evidence; both human and mouse pairs are ortholog-inferred.","localisation_and_range":"PLA2G1B carries a secreted flag [flag]; paracrine or endocrine range is not otherwise reported.","caveats":"No papers were judged (two rows were classed different_entity), so this pair rests on database annotation alone. UniProt notes selectivity against PLA2G2A [DB:UniProt Q13018].","key_references":[],"covers":["LR003103","LR006324"]},"LR001222":{"pair":"PLAU -> ITGAM","headline":"uPA acts through CD11b/Mac-1 independent of uPAR in mouse I/R neutrophil responses; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Postischemic neutrophil adherence and transmigration were reduced in uPA-deficient mice and by WX-340, but not in uPAR-deficient mice, and were reduced by CD11b/Mac-1 blockade [PMID:21969013]. The authors say the process is regulated via CD11b/Mac-1 and does not require uPAR [PMID:21969013].","molecular_requirements":"Mac-1 is CD11b with its partner chain; the dossier names it as ITGAM:ITGB2 in curator notes [PMID:21969013]. Binding requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cremaster muscle in vivo microscopy and hepatic I/R model [PMID:21969013]; leukocyte-transfer experiments. Mouse pair is also listed as non-inferred.","localisation_and_range":"Secreted uPA per flag [flag]; endothelial uPA promotes adherence and leukocyte uPA promotes transmigration [PMID:21969013].","caveats":"Abstract only; uPA-CD11b physical binding is not demonstrated, and CD11b is described as also serving as a uPAR receptor [PMID:21969013].","key_references":[{"PMID":"21969013","why":"uPA-dependent neutrophil transmigration via CD11b/Mac-1, not uPAR"}],"covers":["LR001222","LR004625"]},"LR003112":{"pair":"PLAUR -> ITGA9","headline":"Direct cell-based binding of soluble uPAR to alpha9 (ITGA9) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Paired with beta1 in the paper [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (abstract only); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003112","LR006333"]},"LR001231":{"pair":"PLG -> ITGB1","headline":"Same single paper as the ITGA9 row: plasmin binds alpha9beta1; the beta1 chain alone is not tested.","interaction_type":"direct binding","direction_and_effect":"Plasmin specifically interacts with alpha9beta1, inducing alpha9-CHO cell migration dependent on kringle binding and catalytic activity [PMID:15247268].","molecular_requirements":"Evidence is for the alpha9beta1 heterodimer; ITGB1 alone not tested [PMID:15247268].","affinity_potency":[],"species_and_systems":"Human proteins, recombinant CHO cells; abstract only [PMID:15247268].","localisation_and_range":"Ligand flagged secreted; ITGB1 flagged non-secreted [flag].","caveats":"Beta1 pairs with many alpha chains; only alpha9beta1 shown. Active species is plasmin.","key_references":[{"PMID":"15247268","why":"plasmin-alpha9beta1 interaction"}],"covers":["LR001231","LR004634"]},"LR003121":{"pair":"PODXL -> SELE","headline":"Sialofucosylated PODXL on pancreatic cancer cells acts as a functional E-selectin ligand in flow adhesion assays; one paper, abstract only.","interaction_type":"functional only","direction_and_effect":"PODXL is the ligand and E-selectin the receptor on endothelium-type cells; depleting sialofucosylated PODXL from the cancer cell surface significantly interferes with selectin-dependent adhesion under flow [PMID:22814396].","molecular_requirements":"The functional ligand is the sialofucosylated glycoform of PODXL, not necessarily the bare protein [PMID:22814396]. The abstract treats E- and L-selectin together.","affinity_potency":[],"species_and_systems":"Human metastatic pancreatic cancer cells, immunodepletion, shRNA and flow-based adhesion assays [PMID:22814396]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged transmembrane, not secreted [flag]; contact-dependent (juxtacrine) adhesion.","caveats":"Only one paper, read as an abstract, with E- and L-selectin not separated. No direct binding affinity reported. IntAct holds a co-immunoprecipitation record for P16581-O00592 [DB:IntAct].","key_references":[{"PMID":"22814396","why":"sialofucosylated PODXL as functional E- and L-selectin ligand"}],"covers":["LR003121","LR006342"]},"LR001240":{"pair":"POMC -> MC2R","headline":"POMC-derived ACTH activates MC2R in cell assays; evidence is abstract-level functional work, with the POMC gene standing in for its cleavage product.","interaction_type":"functional only","direction_and_effect":"ACTH, a POMC cleavage product, activates human MC2R and raises a cAMP-reporter signal [PMID:12213892]; ACTH[1-39] and ACTH[1-24] are full agonists at the mouse receptor [PMID:8754753]. Recombinant ASIP inhibits ACTH-stimulated cAMP at hMC2R, nonsurmountably [PMID:9058374]. UniProt lists MC2R as a POMC ligand target [DB:UniProt].","molecular_requirements":"Not reported in our evidence; no accessory subunit is discussed in the dossier.","affinity_potency":[{"value":"EC50 5.5 nM","assay":"cAMP-responsive luciferase reporter","system":"OS-3 cells with human MC2R","cite":"PMID:12213892"},{"value":"KD 0.84 x 10(-9) M","assay":"Scatchard analysis, 125I-ACTH binding (ACTH[1-39])","system":"HeLa cells with mouse ACTH receptor","cite":"PMID:8754753"},{"value":"EC50 57 x 10(-12) M","assay":"cAMP stimulation (ACTH[1-39])","system":"HeLa cells with mouse ACTH receptor","cite":"PMID:8754753"}],"species_and_systems":"Human receptor in OS-3 and OS3 cells [PMID:12213892][PMID:9058374]; mouse receptor in stably transfected HeLa cells [PMID:8754753]. The mouse pair is ortholog-inferred. All three papers were read as abstracts only.","localisation_and_range":"POMC is flagged secreted and MC2R transmembrane [flag]; this implies paracrine or endocrine signalling, but no paper here tests range.","caveats":"The ligand actually tested is ACTH, not full-length POMC. Abstract notes all five melanocortin receptors bind ACTH to some degree, though MC2R is ACTH-selective [PMID:12213892]. No primary direct-binding data with human MC2R in this dossier. Entity name shown for POMC is beta-endorphin, which is not the ligand tested [flag].","key_references":[{"PMID":"12213892","why":"Human MC2R activated by ACTH with EC50 5.5 nM; FGD mutants validate assay"},{"PMID":"8754753","why":"Mouse ACTH receptor binding and agonism, KD and EC50 values"},{"PMID":"9058374","why":"ASIP antagonism of ACTH at hMC2R"}],"covers":["LR001240","LR004642"]},"LR011032":{"pair":"PORCN -> WNT7B","headline":"UniProt notes WNT7B interacts with PORCN, by similarity; no verified evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states WNT7B interacts with PORCN (by similarity) [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No papers shown; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Database-only, by similarity; one paper judged different_entity.","key_references":[],"covers":["LR011032"]},"LR003130":{"pair":"PRG4 -> CD44","headline":"Direct binding of recombinant human PRG4 to CD44 by ELISA and SPR, competing with hyaluronan; one paper, antiproliferative effect depends on CD44.","interaction_type":"direct binding","direction_and_effect":"Recombinant human PRG4 bound CD44 and interfered with HMW hyaluronic acid binding to CD44 [PMID:25708025]. PRG4 suppressed IL-1beta- and TNFalpha-induced proliferation of RA synoviocytes, reversed by a CD44 antibody, so it acts as a competing ligand [PMID:25708025].","molecular_requirements":"Removing sialic acid and O-glycosylations increased CD44 binding by rhPRG4 (P < 0.001) [PMID:25708025]. Binding used recombinant CD44-IgG1Fc; no co-receptor is reported.","affinity_potency":[],"species_and_systems":"Recombinant human PRG4 (CHO-produced) and recombinant CD44; functional work in human RA fibroblast-like synoviocytes and in PRG4-/- mouse synoviocytes [PMID:25708025]. Mouse pair is projected.","localisation_and_range":"PRG4 is flagged secreted [flag]; the paper describes it as a mucinous glycoprotein secreted by synovial fibroblasts and chondrocytes [PMID:25708025]. CD44 is flagged transmembrane [flag].","caveats":"Single paper; the curator read the abstract and the full-text excerpts show methods but no affinity value in our evidence [PMID:25708025]. The effect is antagonist-like relative to hyaluronan, not a classic agonist.","key_references":[{"PMID":"25708025","why":"rhPRG4 binds CD44 by ELISA/SPR, competes with HA"}],"covers":["LR003130","LR006351"]},"LR001303":{"pair":"RLN3 -> RXFP4","headline":"Relaxin-3 binds and activates RXFP4 (GPCR142) with nanomolar potency across species, with a mouse binding-signalling discordance.","interaction_type":"direct binding","direction_and_effect":"Relaxin-3 activates GPCR142 at nanomolar concentrations while other insulin-like peptides do not [PMID:14522967]. It activates ERK1/2, p38MAPK and Akt and causes receptor internalisation, slightly more potently than INSL5 for ERK1/2 and Akt [PMID:27888281]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"GPCR142 couples to calcium mobilisation only via Galpha16, not Gqi5 [PMID:14522967]. Other subunit needs are not reported in our evidence.","affinity_potency":[{"value":"IC50 < 5 nM","assay":"relaxin-3 binding to GPCR142 orthologues","system":"human, mouse, monkey, cow and pig GPCR142","cite":"PMID:15367576"},{"value":"pIC50 8.800000190734863 to 9.0","assay":"GtoPdb affinity range (pIC50)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in recombinant cells; mouse and other species orthologues tested for binding [PMID:15367576]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"Relaxin-3 bound mouse GPCR142 at high affinity but did not stimulate a Ca2+ response with Galpha16, unlike other species; rat GPCR142 is a pseudogene [PMID:15367576]. Papers read as abstracts only; one further abstract was judged review only.","key_references":[{"PMID":"14522967","why":"Identification of relaxin-3 as GPCR142 agonist"},{"PMID":"15367576","why":"Cross-species binding and the mouse functional discordance"},{"PMID":"27888281","why":"Relaxin-3 versus INSL5 signalling at RXFP4"}],"covers":["LR001303","LR004701"]},"LR001312":{"pair":"RSPO2 -> LGR4","headline":"RSPO2 binds and activates LGR4, with binding, functional and genetic evidence.","interaction_type":"direct binding","direction_and_effect":"R-spondins function as ligands of LGR4 and LGR5 [PMID:21693646]. Human RSPO2 mutants show impaired binding to LGR4/5/6 and to RNF43/ZNRF3 [PMID:29769720]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 associates with the Frizzled/Lrp complex [PMID:21727895]. RSPO2 limb function was independent of LGR4/5/6 and ran through RNF43/ZNRF3 [PMID:29769720].","affinity_potency":[{"value":"pEC50 12.52","assay":"Wnt reporter assay","system":"intestinal crypts / reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human proteins in intestinal crypts and reporter assays [PMID:21693646]; human tetra-amelia mutations [PMID:29769720]; mouse gut deletion [PMID:21727895].","localisation_and_range":"RSPO2 secreted per flag [flag].","caveats":"All three papers abstract only. The PMID 21727895 evidence sentence concerns Lgr5/Lgr4 co-expression, not RSPO2 binding. One review-only row exists.","key_references":[{"PMID":"21693646","why":"R-spondins as LGR4/5 ligands, pEC50"},{"PMID":"29769720","why":"RSPO2 mutants lose LGR4/5/6 binding"},{"PMID":"21727895","why":"LGR4/5 mediate R-spondin signalling"}],"covers":["LR001312","LR004709"]},"LR003202":{"pair":"RTN4RL1 -> ADGRB3","headline":"RTN4RL1 binds BAI3 with nanomolar affinity per one paper's family-wide statement; the human pair is projected.","interaction_type":"direct binding","direction_and_effect":"All three RTN4-receptor isoforms bind a TSR domain of BAIs with nanomolar affinity [PMID:34758294]. BAI1- and BAI3-expressing cells aggregated with RTN4R-expressing cells and RTN4RL1 was a top pulldown interactor [PMID:34758294]. Signalling effect is not reported in our evidence for this pair.","molecular_requirements":"The single TSR2 domain of BAI3 bound RTN4Rs and formed a complex by SEC [PMID:34758294]; RTN4RL1 specifically with BAI3 was not shown separately in the excerpts. Co-receptors not reported.","affinity_potency":[],"species_and_systems":"Recombinant ectodomains and HEK 293F cells [PMID:34758294]. The human pair is ortholog-inferred; a mouse pair is not.","localisation_and_range":"Trans-cellular adhesion, so contact-dependent [PMID:34758294]. No secreted flag on either partner [flag].","caveats":"Evidence for this specific pair comes from a statement covering all RTN4R-family members and BAIs; the curator row was recorded from the abstract. The nanomolar Kd values reported (1.9 nM, 30.0 nM) are for other family pairs, not specified for RTN4RL1-BAI3.","key_references":[{"PMID":"34758294","why":"family-wide binding of RTN4Rs to BAI1 and BAI3"}],"covers":["LR003202","LR006422"]},"LR003211":{"pair":"S100A12 -> CD36","headline":"SPR and cell-binding data show S100A12 binds CD36 with low-nanomolar affinity; one paper, human proteins, CHO cell models.","interaction_type":"direct binding","direction_and_effect":"S100A12 binds CD36 at the thrombospondin-1 binding site and drives CD36 membrane translocation and higher CD36 and PPARgamma expression [PMID:27734162]. Activation of Fyn, Lyn or p38 was not observed [PMID:27734162].","molecular_requirements":"CD36 alone was sufficient in CHO-CD36 cells; a CD36-specific antibody blocked binding of labelled S100A12 [PMID:27734162]. S100A12 also binds RAGE in the same system [PMID:27734162].","affinity_potency":[{"value":"low nanomolar range","assay":"surface plasmon resonance, single-cycle kinetics, 0.62-50.0 nM analyte","system":"recombinant and native S100A12 on CD36","cite":"PMID:27734162"}],"species_and_systems":"Human proteins; CHO-K1, CHO-CD36 and CHO-RAGE cell lines [PMID:27734162].","localisation_and_range":"S100A12 is flagged secreted and CD36 transmembrane [flag].","caveats":"Exact Kd values are not in the excerpts we have. Signalling readouts (Fyn, Lyn, p38) were negative, so downstream function is unclear. Upregulation of CD36 may partly reflect RAGE [PMID:27734162].","key_references":[{"PMID":"27734162","why":"SPR and cell binding of S100A12 to CD36"}],"covers":["LR003211"]},"LR003220":{"pair":"S100A4 -> ERBB4","headline":"S100A4 binds ErbB4 (Kd 66.0 nM) and its neuroprotection depends on ErbB4; best-supported of the S100A4-ErbB pairs.","interaction_type":"direct binding","direction_and_effect":"S100A4-induced neuroprotection depends on ErbB4 expression and ErbB2/Akt, and is reduced by anti-ErbB4 antibody or functional NRG/ErbB4 blockade [PMID:30083275].","molecular_requirements":"ErbB2 is needed as a signalling partner though it does not bind S100A4; neuregulin involvement was seen for long-term but not 2 h exposure [PMID:30083275].","affinity_potency":[{"value":"Kd 66.0 \u00b1 26.9 nM","assay":"surface plasmon resonance, S100A4 on immobilized ErbB4","system":"recombinant proteins","cite":"PMID:30083275"}],"species_and_systems":"Cultured hippocampal neurons and dopaminergic neuron models [PMID:30083275]. IntAct lists an SPR record [DB:IntAct].","localisation_and_range":"S100A4 is flagged secreted and ERBB4 transmembrane [flag].","caveats":"Species of cells not stated in excerpts. Abstract-level curation. Role of neuregulin is time-dependent.","key_references":[{"PMID":"30083275","why":"ErbB4-dependent S100A4 neuroprotection"}],"covers":["LR003220","LR006438"]},"LR001330":{"pair":"S100A9 -> TLR4","headline":"S100A9 binding to TLR4 activates MAPK signalling and AML-cell differentiation; abstract-only, plus Reactome complex records.","interaction_type":"functional only","direction_and_effect":"Binding of S100A9 to TLR4 promotes activation of p38, ERK1/2 and JNK, leading to myelomonocytic and monocytic AML cell differentiation; recombinant S100A9 increased AML cell maturation and prolonged survival in an AML mouse model [PMID:28137827]. Agonist. Reactome lists S100A8:S100A9 binding TLR4:LY96 [DB:Reactome] and UniProt describes S100A9 binding TLR4 and AGER as an alarmin [DB:UniProt].","molecular_requirements":"S100A8 prevented S100A9-induced differentiation, so a high S100A9:S100A8 ratio is needed [PMID:28137827]. Reactome models the heterodimer with TLR4:LY96 [DB:Reactome].","affinity_potency":[],"species_and_systems":"AML mouse models and primary human AML samples; both human and mouse pairs are directly supported [PMID:28137827].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Abstract only; binding is stated, not measured with affinity, in our evidence. Two further papers were judged abstract_insufficient and are not shown.","key_references":[{"PMID":"28137827","why":"S100A9-TLR4 signalling drives AML differentiation"}],"covers":["LR001330","LR004727"]},"LR005011":{"pair":"Sbpl -> Tlr2","headline":"PAUF binds TLR2 in receptor screening, ELISA and co-IP; well supported for binding, with biased downstream signalling.","interaction_type":"direct binding","direction_and_effect":"A receptor-pool screen gave a positive binding signal for PAUF to TLR2 only; ELISA with purified TLR2 ECD was dose dependent and co-IP with full-length TLR2 in HEK293T cells confirmed it, suggesting direct interaction without cofactors [PMID:20802527]. PAUF induced ERK phosphorylation via IKK-beta/TPL2/MEK/ERK but did not activate NF-kappaB and inhibited CXCR4-dependent TLR2-mediated NF-kappaB activation [PMID:20802527].","molecular_requirements":"Glycosylated PAUF was the dominant form co-immunoprecipitated with TLR2; CXCR4 associates with the complex [PMID:20802527].","affinity_potency":[],"species_and_systems":"Recombinant proteins and HEK293T/THP-1 cells; The paper calls the protein PAUF; curators mapped it to Sbpl, and the mouse pair is ortholog-inferred. [PMID:20802527]","localisation_and_range":"PAUF is secreted [flag]; also bound TLR2 on the cell surface membrane per the paper's section heading [PMID:20802527].","caveats":"Single paper, read as abstract plus excerpts; no affinity reported.","key_references":[{"PMID":"20802527","why":"Identifies PAUF as TLR2 ligand; binding and signalling"}],"covers":["LR005011"]},"LR003301":{"pair":"SFTPD -> TLR2","headline":"SP-D binds the soluble TLR2 extracellular domain via its CRD; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Natural and recombinant SP-D showed specific binding to soluble TLR2 extracellular domain [PMID:16834340]; functional effect is not reported in our evidence.","molecular_requirements":"Binding is concentration- and Ca2+-dependent, including to deglycosylated receptor, and blocked by a CRD-epitope antibody [PMID:16834340]. Reactome lists TLR2:TLR1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Recombinant soluble human TLR2 with natural and recombinant human SP-D; mouse pair is ortholog-inferred [PMID:16834340].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only; no affinity reported.","key_references":[{"PMID":"16834340","why":"SP-D binds sTLR2 and sTLR4 through the CRD"}],"covers":["LR003301","LR006515"]},"LR002005":{"pair":"SPON1 -> LRP8","headline":"F-spondin effect on migration depends on LRP8 knockdown in one cell study; functional only.","interaction_type":"functional only","direction_and_effect":"The suppressive effect of F-spondin on M-CSF-induced migration was blocked by knockdown of LRP8 and by RAP, a pan-LDL-receptor-family antagonist [PMID:21488757]. Antagonist effect on migration; F-spondin also reduced RANKL-induced multinucleated cell formation.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse RAW 264 osteoclast precursor cells with recombinant F-spondin [PMID:21488757]. Both pairs are ortholog-inferred.","localisation_and_range":"F-spondin secreted, LRP8 transmembrane [flag].","caveats":"Abstract only; no binding data shown, so a direct interaction is inferred. No affinity. No database records.","key_references":[{"PMID":"21488757","why":"LRP8 knockdown blocks F-spondin suppression of migration"}],"covers":["LR002005","LR005333"]},"LR001402":{"pair":"SPON2 -> ITGAM","headline":"Mindin binds Mac-1 (alphaM integrin) directly, with radiolabelled binding and alphaM-I domain mapping; two papers.","interaction_type":"direct binding","direction_and_effect":"Neutrophil adhesion to mindin was blocked by anti-integrin alphaM antibodies [PMID:16105980]. 131I-labelled mindin binds Mac-1 (CD11b/CD18) via the F-spondin fragment to the alphaM-I domain; blocking the alphaM-I domain blocked mindin-induced phagocytosis, and mindin activates Syk/MAPK signalling [PMID:30869196]. Agonist.","molecular_requirements":"Mac-1 (alphaM with beta2, CD11b/CD18); the FS fragment of mindin binds the alphaM-I domain [PMID:30869196].","affinity_potency":[],"species_and_systems":"Human neutrophils and HEK-293 cells [PMID:16105980]; mouse peritoneal macrophages with CRISPR-Cas9 mindin-deficient mice [PMID:30869196]. Human pair ortholog-inferred.","localisation_and_range":"Mindin is an extracellular matrix protein [flag]; also binds bacteria directly [PMID:30869196].","caveats":"Abstracts only. No affinity value in our evidence. No database records.","key_references":[{"PMID":"30869196","why":"131I-mindin binds Mac-1 alphaM-I domain; phagocytosis"},{"PMID":"16105980","why":"Neutrophil adhesion to mindin blocked by anti-alphaM"}],"covers":["LR001402","LR004797"]},"LR001411":{"pair":"SST -> SSTR2","headline":"Somatostatin binds SSTR2 with high affinity in recombinant cells; multiple abstract-level binding papers.","interaction_type":"direct binding","direction_and_effect":"Somatostatin is an agonist; SSTR1 and SSTR2 bind SRIF and SRIF 28 with high affinity [PMID:8702767]. SRIF14 equals SRIF28 in rank order at sst2 [PMID:9652348]. GtoPdb gives pKi 8.9-10.5 [DB:GtoPdb].","molecular_requirements":"SSTR2 alone suffices in transfected cells. Synthetic hexapeptide/octapeptide analogs bind SSTR2 selectively; residues 294-297 (FDFV) in TM7 of murine SSTR2 determine analog affinity [PMID:8702767].","affinity_potency":[{"value":"pKd 9.89","assay":"[125I][Tyr3]octreotide saturation binding","system":"human sst2 in CCL39 cells","cite":"PMID:9652348"},{"value":"pKi 8.9-10.5","assay":"GtoPdb curated range","system":"not reported","cite":"PMID:7988476"}],"species_and_systems":"Human SSTR2 in CHO or CCL39 cells; murine SSTR2 mutagenesis [PMID:1346068][PMID:9652348][PMID:8702767]. Mouse pair is ortholog-inferred.","localisation_and_range":"SST flagged secreted [flag].","caveats":"All abstract-only. The pKd 9.89 is for the octreotide analogue radioligand, not native somatostatin. Several rows concern analogs or comparisons.","key_references":[{"PMID":"1346068","why":"Cloning of SSTR2; somatostatin binding"},{"PMID":"9652348","why":"sst2 pharmacology, SRIF14 = SRIF28"},{"PMID":"8702767","why":"SSTR2 selectivity determinants"}],"covers":["LR001411","LR004806"]},"LR001420":{"pair":"TAC3 -> TACR3","headline":"NKB (TAC3) is the natural agonist of NK3 (TACR3), supported by binding and functional papers on the human receptor.","interaction_type":"direct binding","direction_and_effect":"Agonist. NKB binds with Ki = 0.8 nM and induces Ca++ mobilisation in cells expressing human NK-3 [PMID:9190866]; the human NK-3 receptor expressed in Xenopus oocytes mediates conductance changes in response to NKB, and mammalian cells show NKB-stimulated calcium mobilisation and arachidonic acid release [PMID:1312036].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.8 nM","assay":"NKB inhibition of [125I][MePhe7]NKB binding","system":"CHO cells expressing hNK-3","cite":"PMID:9190866"},{"value":"pEC50 8.4","assay":"functional agonist potency (as recorded by curators)","system":"human NK-3 receptor expression","cite":"PMID:1312036"},{"value":"Kd 39 nM","assay":"[3H]senktide binding","system":"CHO cells, NK-3 homolog","cite":"PMID:8990205"}],"species_and_systems":"Human receptor in CHO, HEK 293 cells and Xenopus oocytes [PMID:9190866] [PMID:1312036] [PMID:8990205]. A mouse interaction is listed but not described by an experiment here.","localisation_and_range":"TAC3 flagged secreted and TACR3 transmembrane [flag].","caveats":"All papers abstract only. The 39 nM Kd is for senktide, not NKB, and the homolog shows some pharmacological differences from canonical NK-3 [PMID:8990205]. Mouse support is not shown by these papers.","key_references":[{"PMID":"9190866","why":"NKB affinity and Ca2+ mobilisation at human NK-3"},{"PMID":"1312036","why":"Cloning of human NK-3 and NKB response"},{"PMID":"8990205","why":"NK-3 homolog binds [125I-MePhe7]NKB"}],"covers":["LR001420","LR006820"]},"LR002014":{"pair":"TAFA4 -> FPR1","headline":"FAM19A4/TAFA4 is reported as an FPR1 agonist from one 2015 paper (abstract only), single-source.","interaction_type":"direct binding","direction_and_effect":"FAM19A4 was reported as a novel FPR1 ligand based on receptor internalization, radioligand binding and receptor blockage, with chemotaxis of macrophages, enhanced zymosan phagocytosis and ROS release [PMID:25109685]. Curators label it an agonist [PMID:25109685].","molecular_requirements":"Mature FAM19A4 is a 95-amino-acid protein [PMID:25109685]. Co-receptors not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and macrophages; in vitro and in vivo phagocytosis [PMID:25109685]. UniProt records for both proteins cite this paper [DB:UniProt].","localisation_and_range":"TAFA4 annotated secreted, FPR1 transmembrane receptor [flag].","caveats":"Paper read as abstract only; no affinity or independent replication in our evidence. UniProt support derives from the same paper [DB:UniProt].","key_references":[{"PMID":"25109685","why":"Reports FAM19A4 as FPR1 ligand with binding, internalization and macrophage assays"}],"covers":["LR002014","LR005342"]},"LR003400":{"pair":"TIMP1 -> CD74","headline":"TIMP-1 shown to bind CD74 by co-IP and confocal microscopy and to trigger ZAP-70 activation; one paper, abstract plus excerpts.","interaction_type":"direct binding","direction_and_effect":"TIMP-1 and CD74 interacted by co-immunoprecipitation and confocal microscopy in CD74-overexpressing cells, and in Namalwa B-lymphoma cells with endogenous CD74 (dot blot and confocal). TIMP-1 binding triggered intracellular ZAP-70 activation, and a synthetic peptide interfering with the CD74 cytokine-binding site abrogated it, consistent with an activating effect [PMID:34391782].","molecular_requirements":"N-terminal TIMP-1 domain (N-TIMP-1) lacking the C-terminal domain was sufficient to bind CD74 and to induce ZAP-70 activation [PMID:34391782]. Co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant TIMP-1 on CD74-overexpressing LX-2 cells and Namalwa B-lymphoma cells; mouse pair is ortholog-inferred [PMID:34391782].","localisation_and_range":"TIMP1 flagged secreted; CD74 flagged transmembrane receptor [flag].","caveats":"Single paper; docking was in silico and the binding evidence is qualitative with no affinity reported. Dossier gives no independent replication.","key_references":[{"PMID":"34391782","why":"TIMP-1-CD74 binding and ZAP-70 activation"}],"covers":["LR003400","LR006601"]},"LR011410":{"pair":"TNC -> ITGA2B:ITGB3","headline":"Supported only by a Reactome record on alphaVbeta3-tenascin; no verified paper for alphaIIb-beta3.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; three papers were judged abstract_insufficient [outcome_counts]. Reactome records an interaction of integrin alphaVbeta3 with tenascin [DB:Reactome].","molecular_requirements":"Complex of ITGA2B and ITGB3 [flag]; the Reactome record concerns alphaVbeta3, not alphaIIbbeta3 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species of experiments not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Database support does not match this complex (alphaV rather than alphaIIb). Likely a spurious or beta3-chain-driven assignment.","key_references":[],"covers":["LR011410"]},"LR002023":{"pair":"TNFRSF14 -> BTLA","headline":"HVEM (TNFRSF14) binds BTLA directly, with structural and binding studies; BTLA signals as an inhibitory receptor.","interaction_type":"direct binding","direction_and_effect":"HVEM was identified as the unique BTLA ligand, and HVEM engagement induced BTLA tyrosine phosphorylation and SHP-2 recruitment and repressed antigen-driven T cell proliferation [PMID:15568026]. Binding of HVEM to BTLA attenuates T cell activation, making it a coinhibitory pair [PMID:15647361]. An HVEM-based mutein acts as a selective BTLA agonist [PMID:29061848].","molecular_requirements":"BTLA bound the most membrane-distal cysteine-rich domain of HVEM, separate from the LIGHT and lymphotoxin-alpha sites [PMID:15568026]. HVEM can form a ternary complex with BTLA and either LIGHT or lymphotoxin alpha [PMID:15647361], and with LIGHT and CD160 [PMID:34709351]. BTLA and CD160 cross-compete for HVEM [PMID:29061848].","affinity_potency":[],"species_and_systems":"Human proteins in the binding papers [PMID:15647361]; the BTLA-HVEM interaction is described as conserved between mouse and human [PMID:15568026]. Crystal structures plus mouse knockin muteins were used [PMID:34709351]. PDB structure 2AW2 [DB:PDB 2AW2]. A mouse pair was projected from human evidence.","localisation_and_range":"HVEM is flagged membrane-bound (not secreted) and BTLA also membrane-bound [flag], so signalling needs cell contact; BTLA may act in cis or trans [DB:UniProt][PMID:19915044].","caveats":"Most papers were read as abstract only. The affinity is described as high but no value is in our evidence [PMID:15647361]. HVEM has other ligands (LIGHT, lymphotoxin alpha, CD160), so BTLA effects must be separated from those [PMID:34709351]. HVEM is the listed ligand, though it is also a TNF-family receptor.","key_references":[{"PMID":"15568026","why":"Identified HVEM as the BTLA ligand and mapped the binding domain"},{"PMID":"15647361","why":"HVEM binds BTLA with high affinity; ternary complex"},{"PMID":"34709351","why":"HVEM structures and muteins separate LIGHT and BTLA/CD160 functions"}],"covers":["LR002023","LR005351"]},"LR001501":{"pair":"TNFSF13 -> FAS","headline":"A single 2000 paper reports APRIL (as TRDL-1alpha) coprecipitating Fas; isolated, unreplicated evidence.","interaction_type":"direct binding","direction_and_effect":"Purified FLAG-tagged TRDL-1alpha, identical in sequence to APRIL, killed Jurkat cells with kinetics like FasL, and in vitro binding showed it coprecipitated Fas and HVEM, suggesting it as an alternate ligand [PMID:10706119]. Effect: pro-death in Jurkat cells, proposed.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins and Jurkat cells [PMID:10706119]. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID]. The mouse pair has no mouse experiment in our evidence.","localisation_and_range":"APRIL is flagged secreted and not transmembrane [flag].","caveats":"Only one paper, read as an abstract; the abstract says the data 'suggested' an alternate ligand role. Coprecipitation does not show Fas as a physiological receptor. No affinity data.","key_references":[{"PMID":"10706119","why":"TRDL-1alpha (APRIL) coprecipitates Fas"}],"covers":["LR001501","LR004892"]},"LR001510":{"pair":"TNFSF4 -> TNFRSF4","headline":"OX40L-OX40 is supported by databases and structures; one abstract-only in vivo paper.","interaction_type":"functional only","direction_and_effect":"The CD134/CD134L interaction provides a strong CD28-independent costimulatory signal in rat small bowel allotransplantation [PMID:12134113].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat transplantation model; pair species human and mouse are orthology-projected [PMID:12134113].","localisation_and_range":"OX40L flagged transmembrane, not secreted [flag].","caveats":"Single paper, abstract only, no direct binding. Binding support comes from PDB 2HEV [DB:PDB 2HEV], IntAct [DB:IntAct] and Reactome [DB:Reactome].","key_references":[{"PMID":"12134113","why":"In vivo costimulation by CD134/CD134L"}],"covers":["LR001510","LR004900"]},"LR002041":{"pair":"WNT2 -> FZD4","headline":"Fzd4 is reported as a Wnt2 receptor in hepatic sinusoidal endothelial cells by pull-down and co-IP; abstract only.","interaction_type":"direct binding","direction_and_effect":"GST pull-down and co-IP showed Fzd4 to be a novel Wnt2 receptor in HSECs; Wnt2 stimulated HSEC proliferation and canonical beta-catenin signalling (agonist annotated) [PMID:18302287].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Isolated hepatic sinusoidal endothelial cells; dossier lists receptor species as rat and ligand as human; human and mouse pairs are ortholog-inferred [PMID:18302287].","localisation_and_range":"Wnt2 flagged secreted [flag]; autocrine in HSECs [PMID:18302287].","caveats":"Abstract only; the pull-down details are not shown. Cell-type-specific finding. No affinity.","key_references":[{"PMID":"18302287","why":"Fzd4 as Wnt2 receptor in HSECs: pull-down and co-IP"}],"covers":["LR002041","LR005367"]},"LR001600":{"pair":"WNT4 -> FZD6","headline":"Several papers support WNT4-FZD6 binding and function, but FZD6 does not carry the canonical signal.","interaction_type":"direct binding","direction_and_effect":"Wnt-4 forms a biochemical complex with the Frizzled-6 CRD in MDCK cells [PMID:15265686]. Fz6 is needed for Wnt4-mediated expansion of mouse fetal liver LSKs, with Rac1/Jnk rather than beta-catenin output [PMID:21541287]. Wnt-4 changes FZD6-GFP mobility in HEK293T/17 cells [PMID:24873871]. Effect is agonist [DB:GtoPdb].","molecular_requirements":"FZD6 CRD suffices for the complex [PMID:15265686]; Wnt4-Fzd6 co-IP also seen [PMID:31216173].","affinity_potency":[],"species_and_systems":"MDCK (canine) [PMID:15265686]; mouse fetal liver [PMID:21541287]; HEK293T/17 human FZD6 [PMID:24873871]; MC3T3 mouse [PMID:31216173].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Frizzled-6 does not appear to transduce Wnt-4's canonical signal in MDCK cells [PMID:15265686]. FRAP shows receptor-level action only [PMID:24873871]. Two papers read as abstract or browser, one unchecked. No affinity in our evidence.","key_references":[{"PMID":"15265686","why":"Wnt-4 complex with Fz6 CRD"},{"PMID":"21541287","why":"Fz6 needed for Wnt4 effect in fetal liver LSKs"},{"PMID":"24873871","why":"WNT-4 alters FZD6 mobility"}],"covers":["LR001600","LR004989"]},"LR004999":{"pair":"WNT5A -> ROR1","headline":"ROR1 binds Wnt5a and mediates NF-kappaB activation; support from two abstract-only papers plus UniProt.","interaction_type":"direct binding","direction_and_effect":"ROR1 binds Wnt5a, which activated NF-kappaB when coexpressed with ROR1 in HEK293 cells and enhanced CLL cell survival, neutralised by anti-ROR1 antisera [PMID:18287027]. A mutated ROR1 failed to activate NF-kB with WNT5A [PMID:27162350]. UniProt describes ROR1 as a receptor for WNT5A activating NFkB and possibly inhibiting WNT3A signalling [DB:UniProt Q01973].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293 cells and human CLL cells [PMID:18287027]; ROR1 variants tested in cells [PMID:27162350].","localisation_and_range":"ROR1 flagged transmembrane [flag].","caveats":"Both papers abstract-only. Binding was shown by anti-tag co-immunoprecipitation [DB:IntAct P41221-Q01973]; no affinity reported.","key_references":[{"PMID":"18287027","why":"ROR1 binds Wnt5a; NF-kappaB and CLL survival"},{"PMID":"27162350","why":"Mutant ROR1 fails to activate NF-kB with WNT5A"}],"covers":["LR001610","LR004999"]},"LR007699":{"pair":"WNT5A -> WIF1","headline":"No verified paper; a single IntAct SPR record only. WIF1 is a Wnt inhibitor, not a receptor.","interaction_type":"database-asserted only","direction_and_effect":"Interaction is annotated as Ligand-Ligand, inhibitory; WIF1 is not flagged as a receptor [flag]. No curator-verified paper.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; IntAct cites surface plasmon resonance [DB:IntAct].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Two papers were read but judged review-only or abstract-insufficient, so none confirms the pair. Support is one database record [DB:IntAct].","key_references":[],"covers":["LR007699"]},"LR005002":{"pair":"WNT7A -> FZD10","headline":"Co-immunoprecipitation and functional data in one endometrial cancer cell abstract; Fzd10 mediates a noncanonical JNK response.","interaction_type":"direct binding","direction_and_effect":"Wnt7a coimmunoprecipitates with Fzd10 (and Fzd5, SFRP4) in Ishikawa cells; Wnt7a signalling through Fzd10 induced a noncanonical JNK-responsive pathway, an agonist effect [PMID:18567805]. SFRP4 suppresses Wnt7a signalling [PMID:18567805].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Ishikawa endometrial cancer cells [PMID:18567805]; the mouse pair is projected from human evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; autocrine and paracrine action reported [PMID:18567805].","caveats":"Abstract only. Co-IP does not prove direct binding.","key_references":[{"PMID":"18567805","why":"Wnt7a co-IPs with Fzd10 and signals via JNK in Ishikawa cells"}],"covers":["LR001613","LR005002"]},"LR002050":{"pair":"WNT7B -> FZD4","headline":"WNT7B-FZD4 rests on a UniProt note; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records the interaction with FZD4 as in vitro [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro per UniProt; details not reported in our evidence [DB:UniProt].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Two papers judged abstract-insufficient, none confirmed. Support is database-only.","key_references":[],"covers":["LR002050","LR005376"]},"LR000601":{"pair":"FGF21 -> FGFR4","headline":"Single functional mitogenesis study shows FGF21 activity on FGFR4-expressing cells; no direct binding or database support in our evidence.","interaction_type":"functional only","direction_and_effect":"Stimulatory: FGFs 19, 21 and 23 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 in a BaF3 mitogenic assay [PMID:16597617].","molecular_requirements":"Not reported in our evidence for FGF21 specifically; the paper notes FGF signalling is modulated by cofactors such as heparan sulfate proteoglycans [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cell lines engineered to express FGFRs; ligand and receptor species unspecified [PMID:16597617]. A mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor flagged transmembrane [flag].","caveats":"The readout is mitogenic activity, not binding; the abstract describes it as a semiquantitative receptor-specificity readout. One paper only, and no database records.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenesis map of FGF receptor specificity"}],"covers":["LR000601","LR004085"]},"LR001321":{"pair":"RSPO4 -> LGR4","headline":"R-spondins bind LGR4 and potentiate Wnt signalling; RSPO4-specific support comes mainly from databases and family-level papers.","interaction_type":"direct binding","direction_and_effect":"R-spondins act as agonist ligands of LGR4 and LGR5, enhancing Wnt/beta-catenin signalling by increasing Wnt-induced LRP6 phosphorylation [PMID:21693646]. Each of the four R-spondins can bind Lgr4, -5 and -6 [PMID:21727895]. GtoPdb lists RSPO4-LGR4 as a full agonist [DB:GtoPdb].","molecular_requirements":"LGR4 does not signal alone: it associates with the Frizzled/Lrp Wnt receptor complex and enhances Wnt signals; it is not coupled to G proteins or beta-arrestin [PMID:21727895][PMID:21693646].","affinity_potency":[],"species_and_systems":"Human cells with Wnt reporter assays and mouse intestinal crypt cultures [PMID:21693646][PMID:21727895]. Mouse pair is projected from human evidence.","localisation_and_range":"RSPO4 annotated as secreted, LGR4 as transmembrane [flag].","caveats":"Both papers were read as abstracts and describe R-spondins generally; RSPO4 is not singled out in them. RSPO1 was the one tested in HEK293 cells [PMID:21727895]. BioGRID, IntAct and Reactome records support binding [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"21693646","why":"R-spondins bind LGR4/5 and potentiate Wnt signalling"},{"PMID":"21727895","why":"Lgr4/5 associate with Frizzled/Lrp and mediate R-spondin signalling"}],"covers":["LR001321","LR004718"]}};